INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11601, 'តើលក្ខខណ្ឌណាបញ្ជាក់ថាទំនាក់ទំនងពីសំណុំ \(A\) ទៅសំណុំ \(B\) ជាអនុគមន៍?', NULL, '["ធាតុមួយនៃ A អាចផ្គូផ្គងនឹងធាតុច្រើននៃ B", "គ្រប់ធាតុនៃ B ត្រូវតែមានរូបភាព", "ធាតុនីមួយៗនៃ A ត្រូវផ្គូផ្គងនឹងធាតុតែមួយគត់នៃ B", "ធាតុទាំងអស់នៃ A ត្រូវផ្គូផ្គងនឹងធាតុដូចគ្នាតែមួយ"]', 2, NULL, 1, 'mcq', 'តាមនិយមន័យ អនុគមន៍ពី A ទៅ B គឺជាក្បួនដែលភ្ជាប់ធាតុនីមួយៗ x នៃ A ទៅនឹងធាតុតែមួយគត់ y នៃ B។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11602, 'គេឱ្យអនុគមន៍ \(f(x) = 4x - 7\)។ គណនាតម្លៃនៃ \(f(3)\)៖', NULL, '["\\(-7\\)", "\\(9\\)", "\\(5\\)", "\\(12\\)"]', 2, NULL, 1, 'mcq', 'f(3) = 4(3) - 7 = 12 - 7 = 5។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11603, 'តើដែនកំណត់នៃអនុគមន៍ពហុធា \(P(x) = 3x^2 - 2x + 1\) គឺជាអ្វី?', NULL, '["\\(D = [0, +\\infty)\\)", "\\(D = \\mathbb{R}^*\\)", "\\(D = \\mathbb{R} \\setminus \\{0\\}\\)", "\\(D = \\mathbb{R}\\)"]', 3, NULL, 1, 'mcq', 'អនុគមន៍ពហុធាកំណត់បានចំពោះគ្រប់ x ជាចំនួនពិត ដូច្នេះ D = R។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11604, 'រកកូអរដោនេចំណុចកាត់អ័ក្សអរដោនេ \((Oy)\) នៃក្រាប \(y = 3x^2 - 4x + 6\)៖', NULL, '["\\((0, -4)\\)", "\\((0, 3)\\)", "\\((0, 6)\\)", "\\((6, 0)\\)"]', 2, NULL, 1, 'mcq', 'ជំនួស x = 0 នាំឱ្យ y = 3(0)^2 - 4(0) + 6 = 6។ ចំណុចកាត់គឺ (0, 6)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11605, 'ក្រាបនៃអនុគមន៍គូមានលក្ខណៈធរណីមាត្រឆ្លុះធៀបនឹងអ្វី?', NULL, '["អ័ក្សអរដោនេ (Oy)", "គល់កូអរដោនេ O", "បន្ទាត់ y = x", "អ័ក្សអាប់ស៊ីស (Ox)"]', 0, NULL, 1, 'mcq', 'អនុគមន៍គូផ្ទៀងផ្ទាត់ f(-x) = f(x) នាំឱ្យក្រាបរបស់វាឆ្លុះធៀបនឹងអ័ក្សឈរ Oy។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-7c85df935c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11606, 'តាមដ្យាក្រាមព្រួញខាងក្រោម តើកន្សោមតំណាងឱ្យអនុគមន៍ \(f\) ពីសំណុំ \(A\) ទៅសំណុំ \(B\) គឺជាអ្វី?', 'g10-7c85df935c.svg', '["\\(f(x) = 2^x\\)", "\\(f(x) = x^2\\)", "\\(f(x) = x + 3\\)", "\\(f(x) = 2x\\)"]', 1, NULL, 1, 'mcq', 'ធាតុ 1 ទៅ 1, 2 ទៅ 4, 3 ទៅ 9, 4 ទៅ 16 ត្រូវនឹងរូបមន្ត f(x) = x^2។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11607, 'គេឱ្យអនុគមន៍ \(f(x) = 2x^2 + 5x - 3\)។ គណនា \(f(-1)\)៖', NULL, '["\\(-10\\)", "\\(0\\)", "\\(-6\\)", "\\(4\\)"]', 2, NULL, 1, 'mcq', 'f(-1) = 2(-1)^2 + 5(-1) - 3 = 2(1) - 5 - 3 = -6។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11608, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{5}{x - 4}\)៖', NULL, '["\\(D = \\mathbb{R} \\setminus \\{4\\}\\)", "\\(D = \\mathbb{R}\\)", "\\(D = \\mathbb{R} \\setminus \\{-4\\}\\)", "\\(D = (4, +\\infty)\\)"]', 0, NULL, 1, 'mcq', 'អនុគមន៍មានន័យកាលណាភាគបែងខុសពីសូន្យ៖ x - 4 \neq 0 \Leftrightarrow x \neq 4។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11609, 'រកកូអរដោនេចំណុចកាត់អ័ក្សអាប់ស៊ីស \((Ox)\) នៃបន្ទាត់ \(y = 2x - 8\)៖', NULL, '["\\((-4, 0)\\)", "\\((0, -8)\\)", "\\((4, 0)\\)", "\\((8, 0)\\)"]', 2, NULL, 1, 'mcq', 'កាត់អ័ក្ស Ox កាលណា y = 0 \Leftrightarrow 2x - 8 = 0 \Leftrightarrow x = 4។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11610, 'រកដែនកំណត់នៃអនុគមន៍ប្រភាគ \(f(x) = \dfrac{x + 2}{2x - 6}\)៖', NULL, '["\\(D = \\mathbb{R}\\)", "\\(D = (3, +\\infty)\\)", "\\(D = \\mathbb{R} \\setminus \\{3\\}\\)", "\\(D = \\mathbb{R} \\setminus \\{-2\\}\\)"]', 2, NULL, 1, 'mcq', '2x - 6 \neq 0 \Leftrightarrow 2x \neq 6 \Leftrightarrow x \neq 3 នាំឱ្យ D = \mathbb{R} \setminus \{3\}។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11611, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{3x - 12}\)៖', NULL, '["\\(D = [12, +\\infty)\\)", "\\(D = [4, +\\infty)\\)", "\\(D = (-\\infty, 4]\\)", "\\(D = (4, +\\infty)\\)"]', 1, NULL, 2, 'mcq', '3x - 12 \ge 0 \Leftrightarrow 3x \ge 12 \Leftrightarrow x \ge 4 នាំឱ្យ D = [4, +\infty)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11612, 'រកសំណុំរូបភាព \(R_f\) នៃអនុគមន៍ \(f(x) = x^2 + 5\) ចំពោះ \(x \in \mathbb{R}\)៖', NULL, '["\\(\\mathbb{R}\\)", "\\([5, +\\infty)\\)", "\\([0, +\\infty)\\)", "\\((5, +\\infty)\\)"]', 1, NULL, 2, 'mcq', 'ដោយ x^2 \ge 0 ចំពោះគ្រប់ x នាំឱ្យ x^2 + 5 \ge 5 ដូច្នេះ R_f = [5, +\infty)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11613, 'គេឱ្យ \(f(x) = 3x + 2\) និង \(g(x) = x^2 - 1\)។ រកកន្សោម \((f \circ g)(x)\)៖', NULL, '["\\(9x^2 + 12x + 3\\)", "\\(3x^2 + 1\\)", "\\(3x^2 - 1\\)", "\\(3x^2 + 2\\)"]', 2, NULL, 2, 'mcq', '(f \circ g)(x) = f(g(x)) = 3(x^2 - 1) + 2 = 3x^2 - 3 + 2 = 3x^2 - 1។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11614, 'រកអនុគមន៍ច្រាស \(f^{-1}(x)\) នៃ \(f(x) = 2x + 6\)៖', NULL, '["\\(f^{-1}(x) = 2x - 6\\)", "\\(f^{-1}(x) = \\dfrac{x - 6}{2}\\)", "\\(f^{-1}(x) = \\dfrac{x + 6}{2}\\)", "\\(f^{-1}(x) = \\dfrac{2}{x - 6}\\)"]', 1, NULL, 2, 'mcq', 'y = 2x + 6 \Leftrightarrow 2x = y - 6 \Leftrightarrow x = \dfrac{y - 6}{2} នាំឱ្យ f^{-1}(x) = \dfrac{x - 6}{2}។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11615, 'តើអនុគមន៍ \(f(x) = x^5 - 3x^3 + 2x\) ជាប្រភេទអនុគមន៍អ្វី?', NULL, '["អនុគមន៍គូ (Even function)", "អនុគមន៍សេស (Odd function)", "អនុគមន៍ថេរ", "មិនគូមិនសេស"]', 1, NULL, 2, 'mcq', 'f(-x) = (-x)^5 - 3(-x)^3 + 2(-x) = -x^5 + 3x^3 - 2x = -f(x) នាំឱ្យ f ជាអនុគមន៍សេស។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11616, 'តើការធ្វើតេស្តបន្ទាត់ឈរ (Vertical Line Test) ប្រើសម្រាប់អ្វី?', NULL, '["ពិនិត្យរកអនុគមន៍ច្រាស", "ពិនិត្យភាពជាអនុគមន៍គូ", "ពិនិត្យថាតើក្រាបដែលបានឱ្យជាក្រាបនៃអនុគមន៍ឬមិនមែន", "ពិនិត្យរកចំណុចកាត់អ័ក្ស Ox"]', 2, NULL, 2, 'mcq', 'បើបន្ទាត់ឈរនីមួយៗកាត់ក្រាបត្រង់យ៉ាងច្រើនមួយចំណុច នោះក្រាបជាតំណាងអនុគមន៍។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11617, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{25 - x^2}\)៖', NULL, '["\\([-5, 5]\\)", "\\((-5, 5)\\)", "\\([0, 5]\\)", "\\((-\\infty, -5] \\cup [5, +\\infty)\\)"]', 0, NULL, 2, 'mcq', '25 - x^2 \ge 0 \Leftrightarrow x^2 \le 25 \Leftrightarrow -5 \le x \le 5 នាំឱ្យ D = [-5, 5]។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11618, 'រកសំណុំរូបភាព \(R_f\) នៃអនុគមន៍ \(f(x) = -x^2 + 4\) ចំពោះ \(x \in \mathbb{R}\)៖', NULL, '["\\([4, +\\infty)\\)", "\\((-\\infty, 0]\\)", "\\((-\\infty, 4]\\)", "\\(\\mathbb{R}\\)"]', 2, NULL, 2, 'mcq', 'ដោយ -x^2 \le 0 នាំឱ្យ -x^2 + 4 \le 4 ដូច្នេះ R_f = (-\infty, 4]។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11619, 'គេឱ្យ \(f(x) = 2x\) និង \(g(x) = x + 5\)។ រកកន្សោម \((g \circ f)(x)\)៖', NULL, '["\\(x + 10\\)", "\\(2x + 5\\)", "\\(2x + 10\\)", "\\(2x^2 + 5\\)"]', 1, NULL, 2, 'mcq', '(g \circ f)(x) = g(f(x)) = g(2x) = 2x + 5។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11620, 'រកអនុគមន៍ច្រាស \(f^{-1}(x)\) នៃ \(f(x) = \dfrac{x - 3}{4}\)៖', NULL, '["\\(f^{-1}(x) = 4x + 3\\)", "\\(f^{-1}(x) = \\dfrac{4}{x - 3}\\)", "\\(f^{-1}(x) = \\dfrac{x + 3}{4}\\)", "\\(f^{-1}(x) = 4x - 3\\)"]', 0, NULL, 2, 'mcq', 'y = \dfrac{x - 3}{4} \Leftrightarrow x - 3 = 4y \Leftrightarrow x = 4y + 3 នាំឱ្យ f^{-1}(x) = 4x + 3។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11621, 'តើអនុគមន៍ \(f(x) = 2x^4 - 7x^2 + 1\) ជាប្រភេទអនុគមន៍អ្វី?', NULL, '["មិនគូមិនសេស", "អនុគមន៍លីនេអ៊ែរ", "អនុគមន៍សេស (Odd function)", "អនុគមន៍គូ (Even function)"]', 3, NULL, 2, 'mcq', 'f(-x) = 2(-x)^4 - 7(-x)^2 + 1 = 2x^4 - 7x^2 + 1 = f(x) នាំឱ្យ f ជាអនុគមន៍គូ។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11622, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{1}{\sqrt{x - 2}}\)៖', NULL, '["\\([2, +\\infty)\\)", "\\((2, +\\infty)\\)", "\\(\\mathbb{R} \\setminus \\{2\\}\\)", "\\((-\\infty, 2)\\)"]', 1, NULL, 2, 'mcq', 'កន្សោមក្រោមរ៉ាឌីកាល់នៅភាគបែងត្រូវតែវិជ្ជមានដាច់ខាត៖ x - 2 > 0 \Leftrightarrow x > 2 នាំឱ្យ D = (2, +\infty)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11623, 'គេឱ្យ \(f(x) = x^2 + 1\) និង \(g(x) = 2x - 3\)។ គណនាតម្លៃនៃ \((f \circ g)(2)\)៖', NULL, '["\\(10\\)", "\\(1\\)", "\\(5\\)", "\\(2\\)"]', 3, NULL, 2, 'mcq', 'g(2) = 2(2) - 3 = 1 នាំឱ្យ (f \circ g)(2) = f(1) = 1^2 + 1 = 2។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11624, 'តើអនុគមន៍ \(f(x) = x^2 + 2x - 1\) ជាប្រភេទអនុគមន៍អ្វី?', NULL, '["មិនគូមិនសេស (Neither even nor odd)", "អនុគមន៍គូ", "អនុគមន៍ថេរ", "អនុគមន៍សេស"]', 0, NULL, 2, 'mcq', 'f(-x) = x^2 - 2x - 1 ខុសពី f(x) និងខុសពី -f(x) ដូច្នេះមិនគូមិនសេសទេ។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11625, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{\dfrac{x - 1}{x + 3}}\)៖', NULL, '["\\((-\\infty, -3] \\cup [1, +\\infty)\\)", "\\((-3, 1]\\)", "\\([-3, 1]\\)", "\\((-\\infty, -3) \\cup [1, +\\infty)\\)"]', 3, NULL, 3, 'mcq', 'លក្ខខណ្ឌ៖ (x - 1)/(x + 3) \ge 0 និង x + 3 \neq 0។ តាមតារាងសញ្ញា ផលចែកវិជ្ជមានកាលណា x < -3 ឬ x \ge 1។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11626, 'រកអនុគមន៍ច្រាស \(f^{-1}(x)\) នៃអនុគមន៍សនិទាន \(f(x) = \dfrac{2x + 1}{x - 3}\)៖', NULL, '["\\(f^{-1}(x) = \\dfrac{3x + 1}{x - 2}\\)", "\\(f^{-1}(x) = \\dfrac{2x - 1}{x + 3}\\)", "\\(f^{-1}(x) = \\dfrac{x - 3}{2x + 1}\\)", "\\(f^{-1}(x) = \\dfrac{3x - 1}{x + 2}\\)"]', 0, NULL, 3, 'mcq', 'y = \dfrac{2x + 1}{x - 3} \Leftrightarrow y(x - 3) = 2x + 1 \Leftrightarrow yx - 2x = 3y + 1 \Leftrightarrow x(y - 2) = 3y + 1 \Leftrightarrow x = \dfrac{3y + 1}{y - 2}។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11627, 'រកតម្លៃ \(m\) ដើម្បីឱ្យអនុគមន៍ \(f(x) = x^2 + 2(m - 1)x + 4\) វិជ្ជមានជានិច្ចចំពោះគ្រប់ \(x \in \mathbb{R}\)៖', NULL, '["\\(m > 3\\)", "\\(-1 < m < 3\\)", "\\(-3 < m < 1\\)", "\\(m < -1 \\text{ ឬ } m > 3\\)"]', 1, NULL, 3, 'mcq', 'f(x) > 0 ជានិច្ចលុះត្រាតែ a = 1 > 0 និង \Delta\'' = (m - 1)^2 - 4 < 0 \Leftrightarrow (m - 1 - 2)(m - 1 + 2) < 0 \Leftrightarrow (m - 3)(m + 1) < 0 \Leftrightarrow -1 < m < 3។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11628, 'គេឱ្យ \(f(x) = \dfrac{1}{1 - x}\) ចំពោះ \(x \neq 0, 1\)។ រកកន្សោមនៃ \((f \circ f)(x)\)៖', NULL, '["\\(x\\)", "\\(\\dfrac{x}{x - 1}\\)", "\\(\\dfrac{x - 1}{x}\\)", "\\(\\dfrac{1}{x}\\)"]', 2, NULL, 3, 'mcq', '(f \circ f)(x) = f\left(\dfrac{1}{1 - x}\right) = \dfrac{1}{1 - \frac{1}{1 - x}} = \dfrac{1}{\frac{1 - x - 1}{1 - x}} = \dfrac{1 - x}{-x} = \dfrac{x - 1}{x}។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11629, 'បើ \(f\) ជាអនុគមន៍សេសកំណត់លើ \(\mathbb{R}\) តើតម្លៃនៃ \(f(x) + f(-x)\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(-2f(x)\\)", "\\(1\\)", "\\(0\\)", "\\(2f(x)\\)"]', 2, NULL, 3, 'mcq', 'ដោយ f ជាអនុគមន៍សេស នាំឱ្យ f(-x) = -f(x)។ ដូច្នេះ f(x) + f(-x) = f(x) - f(x) = 0 ជានិច្ច។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-6e8e8c21bf.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11630, 'ក្រាបខាងក្រោមបង្ហាញពីអនុគមន៍ \(f(x) = 2x - 1\) និងអនុគមន៍ច្រាស \(f^{-1}(x)\)។ រកកូអរដោនេចំណុចប្រសព្វរវាងក្រាបទាំងពីរ៖', 'g10-6e8e8c21bf.svg', '["\\((1, 1)\\)", "\\((2, 2)\\)", "\\((-1, -1)\\)", "\\((0, 0)\\)"]', 0, NULL, 3, 'mcq', 'ចំណុចប្រសព្វស្ថិតនៅលើបន្ទាត់ y = x៖ 2x - 1 = x \Leftrightarrow x = 1 \Rightarrow y = 1។ ចំណុចប្រសព្វគឺ (1, 1)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11631, 'បើ \(f\) ជាអនុគមន៍សេស និង \(g\) ជាអនុគមន៍គូ (ដែល \(g(x) \neq 0\)) តើអនុគមន៍ \(h(x) = \dfrac{f(x)}{g(x)}\) ជាប្រភេទអនុគមន៍អ្វី?', NULL, '["អនុគមន៍គូ", "អនុគមន៍ថេរ", "មិនគូមិនសេស", "អនុគមន៍សេស"]', 3, NULL, 3, 'mcq', 'h(-x) = \dfrac{f(-x)}{g(-x)} = \dfrac{-f(x)}{g(x)} = -h(x) នាំឱ្យ h ជាអនុគមន៍សេស។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11632, 'ក្រុមហ៊ុនជួលរថយន្តមួយគិតថ្លៃសេវា \(C(d) = 30 + 0.25d\) (គិតជាដុល្លារ) ដែល \(d\) ជាចម្ងាយធ្វើដំណើរគិតជាគីឡូម៉ែត្រ។ បើអតិថិជនម្នាក់បង់ប្រាក់អស់ \(65\) ដុល្លារ តើគាត់បានធ្វើដំណើរចម្ងាយប៉ុន្មាន?', NULL, '["140 km", "160 km", "120 km", "150 km"]', 0, NULL, 3, 'mcq', '30 + 0.25d = 65 <=> 0.25d = 35 <=> d = 35 / 0.25 = 140 km។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11633, 'រូបមន្តបំប្លែងសីតុណ្ហភាពពីអង្សាសេ \(C\) ទៅអង្សាហ្វារិនហៃ \(F\) គឺ \(F(C) = \dfrac{9}{5}C + 32\)។ តើអនុគមន៍ច្រាស \(C(F)\) សម្រាប់បំប្លែងពី F មក C វិញគឺជាអ្វី?', NULL, '["\\(C(F) = \\dfrac{5}{9}F - 32\\)", "\\(C(F) = \\dfrac{9}{5}(F - 32)\\)", "\\(C(F) = \\dfrac{5}{9}(F - 32)\\)", "\\(C(F) = \\dfrac{5}{9}(F + 32)\\)"]', 2, NULL, 3, 'mcq', 'F - 32 = \dfrac{9}{5}C \Leftrightarrow C = \dfrac{5}{9}(F - 32)។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11634, 'ចំនួនបាក់តេរីក្នុងមន្ទីរពិសោធន៍កើនឡើងទ្វេដងរៀងរាល់មួយម៉ោងម្តងតាមអនុគមន៍ \(N(t) = 500 \cdot 2^t\) ដែល t ជាពេលវេលាគិតជាម៉ោង។ តើក្រោយរយៈពេល \(4\) ម៉ោង ចំនួនបាក់តេរីមានប៉ុន្មាន?', NULL, '["2000", "16000", "4000", "8000"]', 3, NULL, 3, 'mcq', 'N(4) = 500 * 2^4 = 500 * 16 = 8000។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11635, 'សិប្បកម្មមួយផលិតទំនិញ x គ្រឿងដោយមានថ្លៃដើមសរុប \(C(x) = 1\,500 + 45x\) (ដុល្លារ) និងចំណូលពីការលក់ \(R(x) = 75x\) (ដុល្លារ)។ រកចំនួនផលិតផល x ដើម្បីឱ្យសិប្បកម្មរួចដើម (Break-even point)៖', NULL, '["30 គ្រឿង", "60 គ្រឿង", "50 គ្រឿង", "40 គ្រឿង"]', 2, NULL, 3, 'mcq', 'រួចដើមកាលណា R(x) = C(x) <=> 75x = 1500 + 45x <=> 30x = 1500 <=> x = 50 គ្រឿង។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11636, 'ដ្រូនមួយហោះធ្លាក់ចុះពីលើអាកាសមកដីតាមអនុគមន៍កម្ពស់ \(h(t) = 120 - 4t\) (h គិតជាម៉ែត្រ, t ជាវិនាទី)។ តើរយៈពេលប៉ុន្មានវិនាទីទើបដ្រូនធ្លាក់ចុះដល់ដី?', NULL, '["20 វិនាទី", "25 វិនាទី", "30 វិនាទី", "40 វិនាទី"]', 2, NULL, 3, 'mcq', 'ធ្លាក់ដល់ដីកាលណា h(t) = 0 <=> 120 - 4t = 0 <=> 4t = 120 <=> t = 30 វិនាទី។', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 1, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11637, 'គេឱ្យអនុគមន៍ \(f(x) = 3x^2 - 2x + 1\)។
ក. គណនាតម្លៃនៃ \(f(-2)\)។
ខ. គណនាតម្លៃនៃ \(f(0)\)។
គ. គណនាតម្លៃនៃ \(f(3)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា f(-2) = 3(-2)^2 - 2(-2) + 1 = 3(4) + 4 + 1 = 17 (2 ពិន្ទុ)
គណនា f(0) = 3(0)^2 - 2(0) + 1 = 1 (1 ពិន្ទុ)
គណនា f(3) = 3(3)^2 - 2(3) + 1 = 3(9) - 6 + 1 = 22 (2 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'easy', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11638, 'រកដែនកំណត់នៃបណ្តាអនុគមន៍ខាងក្រោម៖
ក. \(f(x) = \dfrac{2x + 5}{x^2 - 9}\)
ខ. \(g(x) = \sqrt{4 - 2x}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌភាគបែង f: x^2 - 9 ≠ 0 នាំឱ្យ x ≠ 3 និង x ≠ -3 (1.5 ពិន្ទុ)
សន្និដ្ឋានដែនកំណត់ f: D_f = R \ {-3, 3} (1 ពិន្ទុ)
កំណត់លក្ខខណ្ឌក្រោមរ៉ាឌីកាល់ g: 4 - 2x ≥ 0 នាំឱ្យ 2x ≤ 4 ឬ x ≤ 2 (1.5 ពិន្ទុ)
សន្និដ្ឋានដែនកំណត់ g: D_g = (-∞, 2] (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11639, 'សិក្សាភាពជាអនុគមន៍គូ ឬសេស នៃបណ្តាអនុគមន៍ខាងក្រោម៖
ក. \(f(x) = x^3 - 5x\)
ខ. \(g(x) = 4x^4 - 2x^2 + 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា f(-x) = (-x)^3 - 5(-x) = -x^3 + 5x = -(x^3 - 5x) = -f(x) (1.5 ពិន្ទុ)
សន្និដ្ឋាន f(x) ជាអនុគមន៍សេស (1 ពិន្ទុ)
គណនា g(-x) = 4(-x)^4 - 2(-x)^2 + 3 = 4x^4 - 2x^2 + 3 = g(x) (1.5 ពិន្ទុ)
សន្និដ្ឋាន g(x) ជាអនុគមន៍គូ (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11640, 'គេឱ្យអនុគមន៍ពីរ \(f(x) = 2x - 1\) និង \(g(x) = 3x + 4\)។
ក. រកកន្សោមអនុគមន៍បណ្ដាក់ \((f \circ g)(x)\)។
ខ. រកកន្សោមអនុគមន៍បណ្ដាក់ \((g \circ f)(x)\)។
គ. ផ្ទៀងផ្ទាត់ថាតើ \((f \circ g)(x) = (g \circ f)(x)\) ឬទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា (f ∘ g)(x) = f(3x + 4) = 2(3x + 4) - 1 = 6x + 8 - 1 = 6x + 7 (2 ពិន្ទុ)
គណនា (g ∘ f)(x) = g(2x - 1) = 3(2x - 1) + 4 = 6x - 3 + 4 = 6x + 1 (2 ពិន្ទុ)
សន្និដ្ឋានថាមិនស្មើគ្នាទេ: (f ∘ g)(x) ≠ (g ∘ f)(x) ព្រោះ 6x + 7 ≠ 6x + 1 (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11641, 'គេឱ្យអនុគមន៍ \(f(x) = \dfrac{3x - 2}{5}\)។
ក. រកកន្សោមអនុគមន៍ច្រាស \(f^{-1}(x)\)។
ខ. គណនា \((f \circ f^{-1})(x)\) ដើម្បីផ្ទៀងផ្ទាត់លទ្ធផល។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង y = (3x - 2)/5 នាំឱ្យ 5y = 3x - 2 ឬ 3x = 5y + 2 (1.5 ពិន្ទុ)
ទាញរក x = (5y + 2)/3 ដូច្នេះ f^(-1)(x) = (5x + 2)/3 (1.5 ពិន្ទុ)
គណនា (f ∘ f^(-1))(x) = f((5x + 2)/3) = (3 * (5x + 2)/3 - 2) / 5 (1 ពិន្ទុ)
សម្រួលកន្សោម: (5x + 2 - 2) / 5 = 5x / 5 = x ពិត (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'medium', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11642, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{\sqrt{x^2 - 5x + 6}}{x - 4}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌក្រោមរ៉ាឌីកាល់: x^2 - 5x + 6 ≥ 0 (1.5 ពិន្ទុ)
រកឫសសមីការ x^2 - 5x + 6 = 0: x = 2 និង x = 3 នាំឱ្យ x ≤ 2 ឬ x ≥ 3 (1.5 ពិន្ទុ)
កំណត់លក្ខខណ្ឌភាគបែង: x - 4 ≠ 0 នាំឱ្យ x ≠ 4 (1 ពិន្ទុ)
សន្និដ្ឋានដែនកំណត់ចុងក្រោយ: D = (-∞, 2] ∪ [3, 4) ∪ (4, +∞) (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11643, 'គេឱ្យអនុគមន៍ \(f(x) = \dfrac{2x - 1}{x + 3}\)។
ក. រកដែនកំណត់នៃ \(f\)។
ខ. រកកន្សោមអនុគមន៍ច្រាស \(f^{-1}(x)\) និងដែនកំណត់របស់វា។
គ. កំណត់កូអរដោនេចំណុចប្រសព្វរវាងក្រាបទាំងពីរនៅលើបន្ទាត់ \(y = x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ដែនកំណត់ f: x + 3 ≠ 0 នាំឱ្យ D_f = R \ {-3} (1 ពិន្ទុ)
ទាញរក f^(-1): y(x + 3) = 2x - 1 នាំឱ្យ yx - 2x = -3y - 1 ឬ x(y - 2) = -3y - 1 នាំឱ្យ f^(-1)(x) = (-3x - 1)/(x - 2) = (3x + 1)/(2 - x) (1.5 ពិន្ទុ)
ដែនកំណត់ f^(-1): D_(f^-1) = R \ {2} (0.5 ពិន្ទុ)
ដោះស្រាយសមីការប្រសព្វ f(x) = x: (2x - 1)/(x + 3) = x នាំឱ្យ x^2 + 3x = 2x - 1 ឬ x^2 + x + 1 = 0 (1 ពិន្ទុ)
គណនា Delta = 1 - 4 = -3 < 0 សមីការគ្មានឫសពិត នាំឱ្យក្រាបទាំងពីរមិនប្រសព្វគ្នា (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11644, 'គេឱ្យអនុគមន៍លីនេអ៊ែរ \(f(x) = ax + b\) (ដែល \(a \neq 0\))។
ក. កំណត់តម្លៃ \(a\) និង \(b\) ដោយដឹងថា \(f(1) = 5\) និង \(f^{-1}(3) = -1\)។
ខ. សរសេរសមីការអនុគមន៍ \(f(x)\) និង \(f^{-1}(x)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បកប្រែ f^(-1)(3) = -1 ទៅជា f(-1) = 3 (1.5 ពិន្ទុ)
បង្កើតប្រព័ន្ធសមីការ: a(1) + b = 5 និង a(-1) + b = 3 (1.5 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធសមីការ: បូកអង្គនិងអង្គ 2b = 8 នាំឱ្យ b = 4 រួចទាញបាន a = 1 (1 ពិន្ទុ)
សរសេរចម្លើយ: f(x) = x + 4 និង f^(-1)(x) = x - 4 (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11645, 'សិក្សាភាពគូ-សេសនៃអនុគមន៍ខាងក្រោម៖
ក. \(f(x) = \dfrac{x^3 + x}{|x| + 1}\)
ខ. \(g(x) = \sqrt{x^2 + 1} + x^2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យ f(-x): f(-x) = ((-x)^3 + (-x)) / (|-x| + 1) = (-x^3 - x) / (|x| + 1) (1.5 ពិន្ទុ)
ទាញសញ្ញាដកជាកត្តា: f(-x) = -(x^3 + x) / (|x| + 1) = -f(x) នាំឱ្យ f ជាអនុគមន៍សេស (1 ពិន្ទុ)
ពិនិត្យ g(-x): g(-x) = sqrt((-x)^2 + 1) + (-x)^2 = sqrt(x^2 + 1) + x^2 = g(x) (1.5 ពិន្ទុ)
សន្និដ្ឋាន: g(x) ជាអនុគមន៍គូ (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'hard', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11646, 'ក្រុមហ៊ុនទូរស័ព្ទមួយផ្តល់គម្រោងសេវាប្រចាំខែ \(C(m) = 12 + 0.05m\) (គិតជាដុល្លារ) ដែល \(m\) ជាចំនួននាទីហៅចេញលើសកំណត់។
ក. បើលោក សុខ ប្រើអស់ \(180\) នាទីលើស តើគាត់ត្រូវបង់ប្រាក់ប៉ុន្មាន?
ខ. រកអនុគមន៍ច្រាស \(m(C)\) ដែលកំណត់ចំនួននាទីហៅចេញជាអនុគមន៍នៃប្រាក់ត្រូវបង់។
គ. បើខែនេះលោក សុខ ត្រូវបង់ប្រាក់ \(24.50\) ដុល្លារ តើគាត់បានប្រើប្រាស់អស់ប៉ុន្មាននាទីលើស?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា C(180) = 12 + 0.05(180) = 12 + 9 = 21 ដុល្លារ (1.5 ពិន្ទុ)
ទាញរកអនុគមន៍ច្រាស: C - 12 = 0.05m នាំឱ្យ m = (C - 12) / 0.05 = 20(C - 12) = 20C - 240 (2 ពិន្ទុ)
គណនាចំនួននាទីសម្រាប់ C = 24.50: m = 20(24.50 - 12) = 20(12.50) = 250 នាទី (1.5 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11647, 'រោងចក្រខ្នាតតូចមួយផលិតកាតាបសិស្ស។ ថ្លៃដើមផលិតសរុបប្រចាំថ្ងៃគឺ \(C(x) = 300 + 8x\) (ដុល្លារ) និងចំណូលពីការលក់គឺ \(R(x) = 14x\) (ដុល្លារ) ដែល \(x\) ជាចំនួនកាតាបដែលបានផលិតនិងលក់ដាច់។
ក. សរសេរកន្សោមអនុគមន៍ប្រាក់ចំណេញ \(P(x) = R(x) - C(x)\)។
ខ. រកចំនួនកាតាបដែលត្រូវលក់ដើម្បីឱ្យរោងចក្ររួចដើម (Break-even point)។
គ. គណនាប្រាក់ចំណេញបើរោងចក្រផលិតនិងលក់បាន \(120\) កាតាបក្នុងមួយថ្ងៃ។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរកន្សោម P(x) = 14x - (300 + 8x) = 14x - 8x - 300 = 6x - 300 (1.5 ពិន្ទុ)
កំណត់ចំណុចរួចដើម: P(x) = 0 នាំឱ្យ 6x - 300 = 0 ឬ 6x = 300 នាំឱ្យ x = 50 កាតាប (2 ពិន្ទុ)
គណនាប្រាក់ចំណេញ: P(120) = 6(120) - 300 = 720 - 300 = 420 ដុល្លារ (1.5 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11648, 'ការប្តូរប្រាក់ពីប្រាក់ដុល្លារ \(x\) (USD) ទៅជាប្រាក់រៀលតាមអត្រាការប្រាក់ \(f(x) = 4\,100x\) (KHR)។ ភ្នាក់ងារប្តូរប្រាក់កាត់កម្រៃជើងសារ 2% លើប្រាក់រៀលដែលទទួលបាន គឺ \(g(y) = 0.98y\)។
ក. រកអនុគមន៍បណ្ដាក់ \((g \circ f)(x)\) ដែលកំណត់ប្រាក់រៀលសុទ្ធទទួលបានពីប្រាក់ដុល្លារ \(x\)។
ខ. គណនាប្រាក់រៀលសុទ្ធដែលទទួលបានបើភ្ញៀវទេសចរប្តូរប្រាក់ \(250\) ដុល្លារ។
គ. រកអនុគមន៍ច្រាស \((g \circ f)^{-1}\) ដើម្បីគណនាចំនួនដុល្លារដែលត្រូវការដើម្បីទទួលបានប្រាក់រៀលសុទ្ធ \(4,018,000\text{ KHR}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា (g ∘ f)(x) = g(4100x) = 0.98 * 4100x = 4018x (KHR) (1.5 ពិន្ទុ)
គណនាប្រាក់រៀលពី 250 ដុល្លារ: (g ∘ f)(250) = 4018 * 250 = 1,004,500 KHR (1.5 ពិន្ទុ)
ទាញរកអនុគមន៍ច្រាស: x = y / 4018 (1 ពិន្ទុ)
គណនាប្រាក់ដុល្លារ: x = 4018000 / 4018 = 1000 USD (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11649, 'នៅក្នុងរូបវិទ្យា អាំងតង់ស៊ីតេពន្លឺ \(I\) ពីប្រភពពន្លឺមួយថយចុះតាមចម្ងាយ \(d\) (ម៉ែត្រ) តាមអនុគមន៍ \(I(d) = \dfrac{100}{d^2}\) (គិតជា \(\text{W/m}^2\), ចំពោះ \(d > 0\))។
ក. គណនាអាំងតង់ស៊ីតេពន្លឺនៅចម្ងាយ \(d = 2\text{ m}\) និង \(d = 5\text{ m}\)។
ខ. រកអនុគមន៍ច្រាស \(d(I)\) កំណត់ចម្ងាយតាមអាំងតង់ស៊ីតេពន្លឺ។
គ. តើនៅចម្ងាយប៉ុន្មានម៉ែត្រទើបអាំងតង់ស៊ីតេពន្លឺធ្លាក់ចុះមកត្រឹម \(4\text{ W/m}^2\)?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា I(2) = 100 / 2^2 = 100 / 4 = 25 W/m^2 និង I(5) = 100 / 5^2 = 100 / 25 = 4 W/m^2 (2 ពិន្ទុ)
ទាញរក d(I): I = 100 / d^2 នាំឱ្យ d^2 = 100 / I ឬ d = 10 / sqrt(I) (ដោយ d > 0) (1.5 ពិន្ទុ)
គណនាចម្ងាយសម្រាប់ I = 4: d = 10 / sqrt(4) = 10 / 2 = 5 m (1.5 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11650, 'ហាងទំនិញមួយផ្តល់ការបញ្ចុះតម្លៃពីរប្រភេទ៖ ប័ណ្ណបញ្ចុះតម្លៃ 20 ដុល្លារ \(f(x) = x - 20\) និងការបញ្ចុះតម្លៃ 10% គឺ \(g(x) = 0.90x\) (ចំពោះទំនិញតម្លៃដើម x ដុល្លារ, \(x \ge 50\))។
ក. រកកន្សោម \((f \circ g)(x)\) (ចុះ 10% សិន ទើបបញ្ចុះ 20 ដុល្លារតាមក្រោយ)។
ខ. រកកន្សោម \((g \circ f)(x)\) (បញ្ចុះ 20 ដុល្លារសិន ទើបចុះ 10% តាមក្រោយ)។
គ. តើវិធីបញ្ចុះតម្លៃមួយណាផ្តល់តម្លៃទាបជាង (ចំណេញជាង) ដល់អតិថិជន? ចូរពន្យល់ដោយគណនាផលដក។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា (f ∘ g)(x) = f(0.90x) = 0.90x - 20 (1.5 ពិន្ទុ)
គណនា (g ∘ f)(x) = g(x - 20) = 0.90(x - 20) = 0.90x - 18 (1.5 ពិន្ទុ)
ប្រៀបធៀបផលដក: (g ∘ f)(x) - (f ∘ g)(x) = (0.90x - 18) - (0.90x - 20) = 2 ដុល្លារ (1 ពិន្ទុ)
សន្និដ្ឋាន: វិធី (f ∘ g)(x) ផ្តល់តម្លៃទាបជាង 2 ដុល្លារ ដូច្នេះវិធី (f ∘ g) ចំណេញជាង (1 ពិន្ទុ)', 'អនុគមន៍និងក្រាបអនុគមន៍', 'pisa', 0, '10', 'អនុគមន៍និងក្រាបអនុគមន៍', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11701, 'តើសមីការណាជាទម្រង់ទូទៅនៃអនុគមន៍ដឺក្រេទី 2?', NULL, '["\\(y = ax^3 + bx^2 + c\\)", "\\(y = ax + b\\)", "\\(y = \\dfrac{a}{x} + b\\)", "\\(y = ax^2 + bx + c \\quad (a \\neq 0)\\)"]', 3, NULL, 1, 'mcq', 'អនុគមន៍ដឺក្រេទី 2 មានទម្រង់ y = ax^2 + bx + c ដោយ a \neq 0។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-6f1a851568.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11702, 'ក្រាបនៃអនុគមន៍ \(y = -2x^2 + 3x - 5\) មានភាពកោងបែរទៅណា?', 'g10-6f1a851568.svg', '["បែរទៅស្តាំ", "បើកចុះក្រោម (ខ្នងកោងឡើងលើ)", "បែរទៅឆ្វេង", "បើកឡើងលើ"]', 1, NULL, 1, 'mcq', 'ដោយមេគុណ a = -2 < 0 នាំឱ្យប៉ារ៉ាបូលបើកចុះក្រោម។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11703, 'រកសមីការអ័ក្សឆ្លុះនៃប៉ារ៉ាបូល \(y = x^2 - 4x + 5\)៖', NULL, '["\\(x = 4\\)", "\\(y = 2\\)", "\\(x = -2\\)", "\\(x = 2\\)"]', 3, NULL, 1, 'mcq', 'សមីការអ័ក្សឆ្លុះគឺ x = -\dfrac{b}{2a} = -\dfrac{-4}{2(1)} = 2។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11704, 'រកកូអរដោនេកំពូល S នៃប៉ារ៉ាបូល \(y = (x - 3)^2 + 4\)៖', NULL, '["\\(S(-3, 4)\\)", "\\(S(3, -4)\\)", "\\(S(4, 3)\\)", "\\(S(3, 4)\\)"]', 3, NULL, 1, 'mcq', 'តាមទម្រង់កាណូនិច y = a(x - p)^2 + q កំពូលគឺ S(p, q) = S(3, 4)។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11705, 'រកចំណុចកាត់អ័ក្ស Oy នៃប៉ារ៉ាបូល \(y = 2x^2 - 5x + 7\)៖', NULL, '["\\((7, 0)\\)", "\\((0, -5)\\)", "\\((0, 7)\\)", "\\((0, 2)\\)"]', 2, NULL, 1, 'mcq', 'ជំនួស x = 0 នាំឱ្យ y = 7 ដូច្នេះចំណុចកាត់គឺ (0, 7)។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11706, 'បើ \(\Delta > 0\) តើប៉ារ៉ាបូល \(y = ax^2 + bx + c\) កាត់អ័ក្ស Ox ត្រង់ប៉ុន្មានចំណុច?', NULL, '["0 ចំណុច", "3 ចំណុច", "2 ចំណុច", "1 ចំណុច"]', 2, NULL, 1, 'mcq', '\Delta > 0 សមីការ ax^2 + bx + c = 0 មានឫសពីរផ្សេងគ្នា នាំឱ្យកាត់ Ox ត្រង់ 2 ចំណុច។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11707, 'រកកូអរដោនេកំពូលនៃប៉ារ៉ាបូល \(y = 3x^2\)៖', NULL, '["\\((1, 3)\\)", "\\((3, 0)\\)", "\\((0, 3)\\)", "\\(O(0, 0)\\)"]', 3, NULL, 1, 'mcq', 'ទម្រង់ y = ax^2 មានកំពូលនៅគល់កូអរដោនេ O(0, 0) ជានិច្ច។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11708, 'រកចំណុចកាត់អ័ក្ស Ox នៃប៉ារ៉ាបូល \(y = x^2 - 4\)៖', NULL, '["\\((-2, 0) \\text{ និង } (2, 0)\\)", "\\((-4, 0)\\)", "\\((0, -2) \\text{ និង } (0, 2)\\)", "\\((4, 0)\\)"]', 0, NULL, 1, 'mcq', 'y = 0 \Leftrightarrow x^2 - 4 = 0 \Leftrightarrow x = \pm 2។ ចំណុចកាត់គឺ (-2, 0) និង (2, 0)។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11709, 'បើ \(\Delta = 0\) តើក្រាបនៃប៉ារ៉ាបូលមានទំនាក់ទំនងយ៉ាងដូចម្តេចជាមួយអ័ក្ស Ox?', NULL, '["មិនប៉ះនិងមិនកាត់អ័ក្ស Ox", "ប៉ះអ័ក្ស Ox ត្រង់កំពូលរបស់វា", "ស្របនឹងអ័ក្ស Ox", "កាត់អ័ក្ស Ox ត្រង់ពីរចំណុច"]', 1, NULL, 1, 'mcq', '\Delta = 0 នាំឱ្យសមីការមានឫសឌុប ដូច្នេះប៉ារ៉ាបូលប៉ះអ័ក្ស Ox ត្រង់កំពូល។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11710, 'បើ \(\Delta < 0\) តើក្រាបនៃប៉ារ៉ាបូលប្រសព្វនឹងអ័ក្ស Ox ប៉ុន្មានចំណុច?', NULL, '["អនន្តចំណុច", "1 ចំណុច", "2 ចំណុច", "0 ចំណុច (មិនប្រសព្វ)"]', 3, NULL, 1, 'mcq', '\Delta < 0 សមីការគ្មានឫសពិត នាំឱ្យក្រាបមិនកាត់អ័ក្ស Ox ទេ។', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-29a8adff38.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11711, 'រកកូអរដោនេកំពូល S នៃប៉ារ៉ាបូល \(y = x^2 - 6x + 8\)៖', 'g10-29a8adff38.svg', '["\\(S(3, 8)\\)", "\\(S(-3, -1)\\)", "\\(S(3, -1)\\)", "\\(S(-3, 35)\\)"]', 2, NULL, 2, 'mcq', 'x_S = -\dfrac{b}{2a} = 3, \; y_S = 3^2 - 6(3) + 8 = 9 - 18 + 8 = -1 នាំឱ្យ S(3, -1)។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11712, 'រកតម្លៃអប្បបរមានៃអនុគមន៍ \(f(x) = x^2 + 4x + 9\)៖', NULL, '["\\(13\\)", "\\(5\\)", "\\(-2\\)", "\\(9\\)"]', 1, NULL, 2, 'mcq', 'a = 1 > 0 នាំឱ្យមានតម្លៃអប្បបរមាត្រង់ x = -2៖ f(-2) = (-2)^2 + 4(-2) + 9 = 4 - 8 + 9 = 5។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11713, 'សរសេរ \(y = x^2 - 4x + 1\) ជាទម្រង់កាណូនិច \(y = a(x - p)^2 + q\)៖', NULL, '["\\(y = (x + 2)^2 - 3\\)", "\\(y = (x - 2)^2 - 3\\)", "\\(y = (x - 4)^2 - 3\\)", "\\(y = (x - 2)^2 + 1\\)"]', 1, NULL, 2, 'mcq', 'y = (x^2 - 4x + 4) - 4 + 1 = (x - 2)^2 - 3។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11714, 'រកកូអរដោនេចំណុចកាត់អ័ក្ស Ox នៃក្រាប \(y = x^2 - 7x + 12\)៖', NULL, '["\\((2, 0) \\text{ និង } (6, 0)\\)", "\\((-3, 0) \\text{ និង } (-4, 0)\\)", "\\((3, 0) \\text{ និង } (4, 0)\\)", "\\((0, 3) \\text{ និង } (0, 4)\\)"]', 2, NULL, 2, 'mcq', 'x^2 - 7x + 12 = 0 \Leftrightarrow (x - 3)(x - 4) = 0 \Leftrightarrow x = 3 \text{ ឬ } x = 4។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11715, 'បើក្រាប \(y = x^2\) ត្រូវរំកិលទៅស្តាំ 2 ឯកតា និងចុះក្រោម 5 ឯកតា តើសមីការថ្មីគឺអ្វី?', NULL, '["\\(y = (x - 2)^2 + 5\\)", "\\(y = (x - 2)^2 - 5\\)", "\\(y = (x + 2)^2 - 5\\)", "\\(y = (x + 2)^2 + 5\\)"]', 1, NULL, 2, 'mcq', 'រំកិលស្តាំ 2 ជំនួស x ដោយ (x - 2), ចុះក្រោម 5 ដក 5 នាំឱ្យ y = (x - 2)^2 - 5។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11716, 'រកសំណុំចម្លើយនៃវិសមីការ \(x^2 - 4x + 3 \le 0\)៖', NULL, '["\\([-3, -1]\\)", "\\((1, 3)\\)", "\\([1, 3]\\)", "\\((-\\infty, 1] \\cup [3, +\\infty)\\)"]', 2, NULL, 2, 'mcq', 'ឫសគឺ x = 1, 3។ ក្នុងចន្លោះឫសសញ្ញាផ្ទុយពី a = 1 > 0 (គឺអវិជ្ជមាន) នាំឱ្យចម្លើយគឺ [1, 3]។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11717, 'រកតម្លៃអប្បបរមានៃ \(f(x) = x^2 - 2x + 5\) លើចន្លោះបិទ \([0, 3]\)៖', NULL, '["\\(8\\)", "\\(4\\)", "\\(5\\)", "\\(2\\)"]', 1, NULL, 2, 'mcq', 'កំពូលត្រង់ x = 1 ស្ថិតក្នុង [0, 3] នាំឱ្យ f(1) = 1 - 2 + 5 = 4 ជាតម្លៃអប្បបរមា។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11718, 'បើ \(a > 0\) និង \(\Delta < 0\) តើសញ្ញានៃ \(f(x) = ax^2 + bx + c\) យ៉ាងដូចម្តេច?', NULL, '["\\(f(x) \\ge 0\\)", "\\(f(x) < 0 \\text{ ចំពោះគ្រប់ } x \\in \\mathbb{R}\\)", "\\(f(x) > 0 \\text{ ចំពោះគ្រប់ } x \\in \\mathbb{R}\\)", "\\(f(x) = 0\\)"]', 2, NULL, 2, 'mcq', '\Delta < 0 នាំឱ្យ f(x) មានសញ្ញាតាម a ជានិច្ច ដូច្នេះ f(x) > 0 ចំពោះគ្រប់ x \in \mathbb{R}។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11719, 'រកកូអរដោនេកំពូល S នៃប៉ារ៉ាបូល \(y = -2x^2 + 8x - 5\)៖', NULL, '["\\(S(-2, -29)\\)", "\\(S(4, 3)\\)", "\\(S(2, 3)\\)", "\\(S(2, -5)\\)"]', 2, NULL, 2, 'mcq', 'x_S = -\dfrac{8}{2(-2)} = 2, \; y_S = -2(4) + 8(2) - 5 = -8 + 16 - 5 = 3 នាំឱ្យ S(2, 3)។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11720, 'រកតម្លៃអតិបរមានៃអនុគមន៍ \(f(x) = -x^2 + 6x - 2\)៖', NULL, '["\\(-2\\)", "\\(11\\)", "\\(3\\)", "\\(7\\)"]', 3, NULL, 2, 'mcq', 'a = -1 < 0 នាំឱ្យមានតម្លៃអតិបរមាត្រង់ x = 3៖ f(3) = -(9) + 18 - 2 = 7។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11721, 'សរសេរ \(y = 2x^2 - 8x + 11\) ជាទម្រង់កាណូនិច៖', NULL, '["\\(y = 2(x - 2)^2 + 3\\)", "\\(y = 2(x + 2)^2 + 3\\)", "\\(y = (2x - 4)^2 + 3\\)", "\\(y = 2(x - 2)^2 + 11\\)"]', 0, NULL, 2, 'mcq', 'y = 2(x^2 - 4x + 4) - 8 + 11 = 2(x - 2)^2 + 3។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11722, 'រកសំណុំចម្លើយនៃវិសមីការ \(x^2 - 5x + 6 > 0\)៖', NULL, '["\\((2, 3)\\)", "\\([2, 3]\\)", "\\((-\\infty, 2) \\cup (3, +\\infty)\\)", "\\((-\\infty, 2] \\cup [3, +\\infty)\\)"]', 2, NULL, 2, 'mcq', 'ឫសគឺ x = 2, 3។ វិជ្ជមាននៅក្រៅចន្លោះឫស នាំឱ្យចម្លើយគឺ (-\infty, 2) \cup (3, +\infty)។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11723, 'រកតម្លៃអតិបរមានៃ \(f(x) = x^2 - 2x + 5\) លើចន្លោះបិទ \([0, 3]\)៖', NULL, '["\\(9\\)", "\\(8\\)", "\\(5\\)", "\\(4\\)"]', 1, NULL, 2, 'mcq', 'f(0) = 5, f(3) = 9 - 6 + 5 = 8។ តម្លៃអតិបរមាលើចន្លោះនេះគឺ 8 (ត្រង់ x = 3)។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11724, 'បើ \(a < 0\) និង \(\Delta < 0\) តើសញ្ញានៃ \(f(x) = ax^2 + bx + c\) យ៉ាងដូចម្តេច?', NULL, '["\\(f(x) \\le 0\\)", "\\(f(x) = 0\\)", "\\(f(x) > 0 \\text{ ចំពោះគ្រប់ } x \\in \\mathbb{R}\\)", "\\(f(x) < 0 \\text{ ចំពោះគ្រប់ } x \\in \\mathbb{R}\\)"]', 3, NULL, 2, 'mcq', 'ដោយ a < 0 និង \Delta < 0 នាំឱ្យ f(x) < 0 ចំពោះគ្រប់ x \in \mathbb{R}។', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11725, 'រកតម្លៃ \(m\) ដើម្បីឱ្យប៉ារ៉ាបូល \(y = x^2 - 2mx + m + 2\) ប៉ះអ័ក្ស Ox៖', NULL, '["\\(m = -1 \\text{ ឬ } m = 2\\)", "\\(m = 2\\)", "\\(m = 1 \\text{ ឬ } m = -2\\)", "\\(m = 0\\)"]', 0, NULL, 3, 'mcq', 'ប៉ះ Ox លុះត្រាតែ \Delta\'' = m^2 - (m + 2) = 0 \Leftrightarrow m^2 - m - 2 = 0 \Leftrightarrow m = -1 \text{ ឬ } m = 2។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11726, 'រកតម្លៃ \(m\) ដើម្បីឱ្យក្រាប \(y = (m - 1)x^2 + 4x + 2\) កាត់អ័ក្ស Ox ត្រង់ពីរចំណុចផ្សេងគ្នា៖', NULL, '["\\(m > 3\\)", "\\(m < 3\\)", "\\(m \\le 3 \\text{ និង } m \\neq 1\\)", "\\(m < 3 \\text{ និង } m \\neq 1\\)"]', 3, NULL, 3, 'mcq', 'លក្ខខណ្ឌ៖ a = m - 1 \neq 0 \Rightarrow m \neq 1 និង \Delta\'' = 4 - 2(m - 1) > 0 \Leftrightarrow 4 - 2m + 2 > 0 \Leftrightarrow 2m < 6 \Leftrightarrow m < 3។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11727, 'រកតម្លៃអតិបរមានៃ \(f(x) = -x^2 + 4x + 1\) លើចន្លោះបិទ \([-1, 1]\)៖', NULL, '["\\(5\\)", "\\(1\\)", "\\(4\\)", "\\(-4\\)"]', 2, NULL, 3, 'mcq', 'កំពូលគឺ x = 2 ស្ថិតនៅក្រៅចន្លោះ [-1, 1]។ អនុគមន៍កើនលើ [-1, 1] ដូច្នេះតម្លៃអតិបរមាគឺ f(1) = -(1) + 4 + 1 = 4។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11728, 'ប៉ារ៉ាបូលមួយកាត់តាមចំណុច \(A(1, 0),\; B(3, 0)\) និង \(C(0, 6)\)។ រកសមីការរបស់វា៖', NULL, '["\\(y = -2x^2 + 8x + 6\\)", "\\(y = 2x^2 - 8x + 6\\)", "\\(y = x^2 - 4x + 3\\)", "\\(y = 2x^2 + 8x + 6\\)"]', 1, NULL, 3, 'mcq', 'y = a(x - 1)(x - 3) = a(x^2 - 4x + 3)។ កាត់ (0, 6) នាំឱ្យ 6 = a(3) => a = 2។ ដូចនេះ y = 2x^2 - 8x + 6។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11729, 'រកកូអរដោនេចំណុចប្រសព្វរវាងប៉ារ៉ាបូល \(y = x^2 - 3x + 2\) និងបន្ទាត់ \(y = x - 1\)៖', NULL, '["\\((1, 0) \\text{ និង } (3, 2)\\)", "\\((0, 2) \\text{ និង } (1, 0)\\)", "\\((2, 1) \\text{ និង } (3, 0)\\)", "\\((-1, -2) \\text{ និង } (3, 2)\\)"]', 0, NULL, 3, 'mcq', 'x^2 - 3x + 2 = x - 1 \Leftrightarrow x^2 - 4x + 3 = 0 \Leftrightarrow x = 1 \Rightarrow y = 0 \text{ ឬ } x = 3 \Rightarrow y = 2។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11730, 'រកចន្លោះតម្លៃ \(m\) ដើម្បីឱ្យវិសមីការ \(x^2 - 2x + m > 0\) ផ្ទៀងផ្ទាត់ចំពោះគ្រប់ \(x \in \mathbb{R}\)៖', NULL, '["\\(m > 1\\)", "\\(m \\ge 1\\)", "\\(m < 1\\)", "\\(m > 0\\)"]', 0, NULL, 3, 'mcq', 'វិសមីការផ្ទៀងផ្ទាត់គ្រប់ x លុះត្រាតែ a = 1 > 0 និង \Delta\'' = (-1)^2 - m < 0 \Leftrightarrow 1 - m < 0 \Leftrightarrow m > 1។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11731, 'ប៉ារ៉ាបូល \(y = ax^2 + bx + c\) មានកំពូល \(S(1, 4)\) និងកាត់តាម \((0, 3)\)។ រកតម្លៃមេគុណ \(a, b, c\)៖', NULL, '["\\(a = 2,\\; b = -4,\\; c = 3\\)", "\\(a = -1,\\; b = -2,\\; c = 3\\)", "\\(a = 1,\\; b = -2,\\; c = 3\\)", "\\(a = -1,\\; b = 2,\\; c = 3\\)"]', 3, NULL, 3, 'mcq', 'y = a(x - 1)^2 + 4។ កាត់ (0, 3) នាំឱ្យ 3 = a(0 - 1)^2 + 4 => a + 4 = 3 => a = -1។ y = -(x^2 - 2x + 1) + 4 = -x^2 + 2x + 3។', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-e7473ad304.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11732, 'គេបាញ់គ្រាប់កាំភ្លើងធំមួយឡើងលើតាមគន្លង \(h(t) = -5t^2 + 40t\) ដែល h ជាកម្ពស់ (ម៉ែត្រ) និង t ជាពេលវេលា (វិនាទី)។ រកកម្ពស់អតិបរមាដែលគ្រាប់កាំភ្លើងឡើងដល់៖', 'g10-e7473ad304.svg', '["80 m", "40 m", "100 m", "60 m"]', 0, NULL, 3, 'mcq', 't = -40 / (2(-5)) = 4 s នាំឱ្យ h(4) = -5(16) + 40(4) = -80 + 160 = 80 m។', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11733, 'ក្រុមហ៊ុនមួយមានអនុគមន៍ប្រាក់ចំណេញប្រចាំសប្តាហ៍ \(P(x) = -x^2 + 60x - 500\) (គិតជាពាន់ដុល្លារ) ដែល x ជាចំនួនផលិតផល។ តើក្រុមហ៊ុនត្រូវផលិត x ប៉ុន្មានដើម្បីបានប្រាក់ចំណេញខ្ពស់បំផុត?', NULL, '["25 ផលិតផល", "60 ផលិតផល", "40 ផលិតផល", "30 ផលិតផល"]', 3, NULL, 3, 'mcq', 'ប្រាក់ចំណេញអតិបរមាសម្រេចបានត្រង់កំពូល x = -60 / (2(-1)) = 30 ផលិតផល។', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11734, 'ស្ពានខ្សែយោងមួយមានរាងប៉ារ៉ាបូលតាមសមីការ \(y = 0.005x^2\) (គិតជាម៉ែត្រ) ដែល x ជាចម្ងាយផ្ដេកពីចំណុចកណ្តាលស្ពាន។ រកកម្ពស់ខ្សែយោងនៅចម្ងាយ \(x = 40\text{ m}\) ពីចំណុចកណ្តាល៖', NULL, '["8 m", "16 m", "4 m", "10 m"]', 0, NULL, 3, 'mcq', 'y = 0.005 * 40^2 = 0.005 * 1600 = 8 m។', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11735, 'កសិករម្នាក់មានរបងលួសសំណាញ់ប្រវែង \(40\text{ m}\) សម្រាប់ធ្វើរបងសួនច្បាររាងចតុកោណកែងដោយផ្អែកលើជញ្ជាំងផ្ទះម្ខាង (ធ្វើរបងតែ 3 ជ្រុង: ទទឹង 2x និងបណ្តោយ y)។ ផ្ទៃក្រឡាអតិបរមាដែលគាត់អាចព័ទ្ធបានគឺ៖', NULL, '["\\(200\\text{ m}^2\\)", "\\(150\\text{ m}^2\\)", "\\(100\\text{ m}^2\\)", "\\(400\\text{ m}^2\\)"]', 0, NULL, 3, 'mcq', '2x + y = 40 => y = 40 - 2x។ A(x) = x(40 - 2x) = -2x^2 + 40x។ កំពូល x = 10 m នាំឱ្យ A = 10(20) = 200 m^2។', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11736, 'រោងកុនមួយលក់សំបុត្រតម្លៃ x ដុល្លារ។ ចំនួនអ្នកទិញសំបុត្រគឺ \(q = 200 - 10x\) នាក់។ ចំណូលសរុបគឺ \(R(x) = x(200 - 10x) = -10x^2 + 200x\)។ តើរោងកុនត្រូវកំណត់តម្លៃសំបុត្រ x ប៉ុន្មានដើម្បីទទួលបានចំណូលអតិបរមា?', NULL, '["15 ដុល្លារ", "8 ដុល្លារ", "10 ដុល្លារ", "20 ដុល្លារ"]', 2, NULL, 3, 'mcq', 'x = -200 / (2(-10)) = 200 / 20 = 10 ដុល្លារ។', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 1, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11737, 'គេឱ្យអនុគមន៍ដឺក្រេទី 2 \(y = x^2 - 4x + 3\)។
ក. សរសេរសមីការជាទម្រង់កាណូនិច \(y = a(x - p)^2 + q\)។
ខ. កំណត់កូអរដោនេកំពូល \(S\) នៃប៉ារ៉ាបូល។
គ. សរសេរសមីការអ័ក្សឆ្លុះនៃប៉ារ៉ាបូល។', NULL, '[]', 0, NULL, 5, 'writing', 'បំប្លែងជាទម្រង់កាណូនិច: y = (x^2 - 4x + 4) - 4 + 3 = (x - 2)^2 - 1 (2 ពិន្ទុ)
ទាញរកកំពូល: S(p, q) = S(2, -1) (2 ពិន្ទុ)
សមីការអ័ក្សឆ្លុះ: x = 2 (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'easy', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11738, 'សិក្សាអថេរភាព និងសង់តារាងអថេរភាពនៃអនុគមន៍ \(y = -x^2 + 4x - 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់មេគុណ a = -1 < 0 ប៉ារ៉ាបូលបែរភាពប៉ោងឡើងលើ (បើកចុះក្រោម) (1 ពិន្ទុ)
គណនាកំពូល S: x_S = -4 / (2(-1)) = 2, y_S = -(2)^2 + 4(2) - 3 = 1 នាំឱ្យ S(2, 1) (1.5 ពិន្ទុ)
ទិសដៅអថេរភាព: កើនលើ (-∞, 2] និងចុះលើ [2, +∞) (1.5 ពិន្ទុ)
សង់តារាងអថេរភាពបង្ហាញ x ពី -∞ ទៅ 2 ទៅ +∞ និង y កើនពី -∞ ឡើងដល់ 1 រួចចុះទៅ -∞ (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11739, 'គេឱ្យអនុគមន៍ \(y = x^2 - 5x + 4\)។
ក. រកកូអរដោនេចំណុចកាត់អ័ក្សអាប់ស៊ីស Ox។
ខ. រកកូអរដោនេចំណុចកាត់អ័ក្សអរដោនេ Oy។
គ. រកតម្លៃអប្បបរមានៃអនុគមន៍នេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោះស្រាយ x^2 - 5x + 4 = 0: x = 1, 4 នាំឱ្យចំណុចកាត់ Ox គឺ (1, 0) និង (4, 0) (2 ពិន្ទុ)
ជំនួស x = 0: y = 4 នាំឱ្យចំណុចកាត់ Oy គឺ (0, 4) (1 ពិន្ទុ)
គណនាតម្លៃអប្បបរមាត្រង់ x = 5/2 = 2.5: y_min = (2.5)^2 - 5(2.5) + 4 = 6.25 - 12.5 + 4 = -2.25 = -9/4 (2 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11740, 'ដោះស្រាយបណ្តាវិសមីការដឺក្រេទី 2 ខាងក្រោម៖
ក. \(x^2 - 6x + 8 \le 0\)
ខ. \(-2x^2 + 5x - 2 > 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រកឫស x^2 - 6x + 8 = 0: x = 2 និង x = 4 (1 ពិន្ទុ)
ចម្លើយវិសមីការ ក: [2, 4] (1.5 ពិន្ទុ)
ដោះស្រាយ 2x^2 - 5x + 2 < 0: ឫស x = 1/2 និង x = 2 (1 ពិន្ទុ)
ចម្លើយវិសមីការ ខ: (1/2, 2) (1.5 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11741, 'រកតម្លៃអតិបរមានិងតម្លៃអប្បបរមានៃអនុគមន៍ \(f(x) = x^2 - 4x + 7\) នៅលើចន្លោះបិទ \([0, 3]\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រកអាប់ស៊ីសកំពូល: x_S = -(-4) / 2 = 2 ស្ថិតក្នុងចន្លោះ [0, 3] (1.5 ពិន្ទុ)
គណនាតម្លៃ f(2) = 2^2 - 4(2) + 7 = 4 - 8 + 7 = 3 (1.5 ពិន្ទុ)
គណនាតម្លៃចុងចន្លោះ: f(0) = 7 និង f(3) = 9 - 12 + 7 = 4 (1 ពិន្ទុ)
សន្និដ្ឋាន: តម្លៃអប្បបរមាគឺ 3 (ត្រង់ x = 2) និងតម្លៃអតិបរមាគឺ 7 (ត្រង់ x = 0) (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'medium', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11742, 'គេឱ្យប៉ារ៉ាបូល \((P): y = x^2 - 2x - 3\) និងបន្ទាត់ \((d): y = mx - 4\)។
ក. សរសេរសមីការអាប់ស៊ីសចំណុចប្រសព្វរវាង \((P)\) និង \((d)\)។
ខ. កំណត់តម្លៃ \(m\) ដើម្បីឱ្យបន្ទាត់ \((d)\) ប៉ះប៉ារ៉ាបូល \((P)\)។
គ. រកកូអរដោនេចំណុចប៉ះចំពោះតម្លៃ \(m\) នីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'សមីការអាប់ស៊ីស: x^2 - 2x - 3 = mx - 4 នាំឱ្យ x^2 - (m + 2)x + 1 = 0 (1.5 ពិន្ទុ)
លក្ខខណ្ឌប៉ះ: Delta = (m + 2)^2 - 4 = 0 នាំឱ្យ (m + 2)^2 = 4 នាំឱ្យ m + 2 = 2 ឬ m + 2 = -2 នាំឱ្យ m = 0 ឬ m = -4 (1.5 ពិន្ទុ)
ករណី m = 0: x^2 - 2x + 1 = 0 នាំឱ្យ x = 1, y = -4 នាំឱ្យចំណុចប៉ះ (1, -4) (1 ពិន្ទុ)
ករណី m = -4: x^2 + 2x + 1 = 0 នាំឱ្យ x = -1, y = 0 នាំឱ្យចំណុចប៉ះ (-1, 0) (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11743, 'រកតម្លៃ \(m\) ដើម្បីឱ្យវិសមីការ \((m - 2)x^2 + 2(m - 2)x + 3 > 0\) ផ្ទៀងផ្ទាត់ចំពោះគ្រប់ចំនួនពិត \(x \in \mathbb{R}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ករណី m - 2 = 0 គឺ m = 2: វិសមីការក្លាយជា 0x^2 + 0x + 3 = 3 > 0 ពិតជានិច្ចគ្រប់ x នាំឱ្យ m = 2 យកបាន (1.5 ពិន្ទុ)
ករណី m ≠ 2: ត្រូវមាន a = m - 2 > 0 នាំឱ្យ m > 2 (1 ពិន្ទុ)
និង Delta'' = (m - 2)^2 - 3(m - 2) < 0 នាំឱ្យ (m - 2)(m - 2 - 3) < 0 នាំឱ្យ (m - 2)(m - 5) < 0 នាំឱ្យ 2 < m < 5 (1.5 ពិន្ទុ)
ផ្គួបករណីទាំងពីរ: 2 ≤ m < 5 (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11744, 'កំណត់សមីការប៉ារ៉ាបូល \(y = ax^2 + bx + c\) ដោយដឹងថាវាឆ្លងកាត់ចំណុចបី \(A(1, 2),\; B(-1, 8),\; C(2, 5)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតប្រព័ន្ធសមីការ: តាម A(1, 2): a + b + c = 2 (1); តាម B(-1, 8): a - b + c = 8 (2); តាម C(2, 5): 4a + 2b + c = 5 (3) (1.5 ពិន្ទុ)
ដក (1) និង (2): 2b = -6 នាំឱ្យ b = -3 (1 ពិន្ទុ)
ជំនួស b = -3 ចូល (1) និង (3): a + c = 5 និង 4a + c = 11 (1 ពិន្ទុ)
ដកសមីការទាំងពីរ: 3a = 6 នាំឱ្យ a = 2 រួចទាញបាន c = 3 (1 ពិន្ទុ)
សន្និដ្ឋានសមីការប៉ារ៉ាបូល: y = 2x^2 - 3x + 3 (0.5 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11745, 'រកតម្លៃអតិបរមានិងអប្បបរមានៃអនុគមន៍ \(f(x) = -x^2 + 2x + 3\) លើចន្លោះបិទ \([2, 5]\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រកកំពូល: x_S = -2 / (2(-1)) = 1 (1.5 ពិន្ទុ)
កត់សម្គាល់កំពូល x = 1 ស្ថិតនៅខាងឆ្វេងចន្លោះ [2, 5] (1 < 2) (1 ពិន្ទុ)
ដោយ a = -1 < 0 អនុគមន៍ចុះលើ [1, +∞) ដូច្នេះ f(x) ចុះលើ [2, 5] (1 ពិន្ទុ)
គណនាតម្លៃចុងចន្លោះ: f(2) = -(4) + 4 + 3 = 3 (តម្លៃអតិបរមា) (0.75 ពិន្ទុ)
គណនា f(5) = -(25) + 10 + 3 = -12 (តម្លៃអប្បបរមា) (0.75 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'hard', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11746, 'កីឡាករម្នាក់ទាត់បាល់មួយឡើងលើតាមគន្លងប៉ារ៉ាបូលដែលមានសមីការ \(h(t) = -5t^2 + 15t + 2\) ដែល h ជាកម្ពស់គិតជាម៉ែត្រ និង t ជាពេលវេលាគិតជាវិនាទី។
ក. រកកម្ពស់ដំបូងនៃគ្រាប់បាល់នៅពេលទាត់ចេញ (t = 0)។
ខ. រយៈពេលប៉ុន្មានវិនាទីទើបបាល់ឡើងដល់ចំណុចខ្ពស់បំផុត? គណនាកម្ពស់ខ្ពស់បំផុតនោះ។
គ. តើគ្រាប់បាល់ធ្លាក់ចុះដល់ដី (h = 0) នៅវិនាទីទីប៉ុន្មាន? (យក \(\sqrt{265} \approx 16.28\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកម្ពស់ដំបូង: h(0) = 2 m (1 ពិន្ទុ)
រកពេលវេលាដល់កំពូល: t = -15 / (2(-5)) = 1.5 វិនាទី (1 ពិន្ទុ)
គណនាកម្ពស់អតិបរមា: h(1.5) = -5(2.25) + 15(1.5) + 2 = -11.25 + 22.5 + 2 = 13.25 m (1.5 ពិន្ទុ)
ដោះស្រាយ -5t^2 + 15t + 2 = 0 នាំឱ្យ 5t^2 - 15t - 2 = 0: Delta = 225 + 40 = 265 (0.75 ពិន្ទុ)
ទាញរក t = (15 + 16.28) / 10 = 31.28 / 10 ≈ 3.13 វិនាទី (យក t > 0) (0.75 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11747, 'កសិករម្នាក់មានសំណាញ់លួសប្រវែង \(60\text{ m}\) សម្រាប់ធ្វើរបងដីចម្ការរាងចតុកោណកែងមួយកន្លែងនៅតាមមាត់ព្រែកត្រង់មួយ ដោយមិនបាច់ធ្វើរបងនៅខាងមាត់ព្រែកឡើយ (ធ្វើតែ 3 ជ្រុង: ទទឹង 2x និងបណ្តោយ y ស្របមាត់ព្រែក)។
ក. សរសេរប្រវែងបណ្តោយ \(y\) ជាអនុគមន៍នៃទទឹង \(x\)។
ខ. សរសេរកន្សោមផ្ទៃក្រឡា \(A(x)\) នៃដីចម្ការជាអនុគមន៍ដឺក្រេទី 2 នៃ \(x\)។
គ. កំណត់វិមាត្រ \(x\) និង \(y\) ដើម្បីឱ្យផ្ទៃក្រឡាដីចម្ការធំបំផុត រួចគណនាផ្ទៃក្រឡាធំបំផុតនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ទំនាក់ទំនងប្រវែងរបង: 2x + y = 60 នាំឱ្យ y = 60 - 2x (m) (1 ពិន្ទុ)
កន្សោមផ្ទៃក្រឡា: A(x) = x * y = x(60 - 2x) = -2x^2 + 60x (m^2) (1.5 ពិន្ទុ)
រក x ឱ្យផ្ទៃក្រឡាអតិបរមា: x = -60 / (2(-2)) = 15 m (1 ពិន្ទុ)
ទាញរក y: y = 60 - 2(15) = 30 m (0.5 ពិន្ទុ)
គណនាផ្ទៃក្រឡាអតិបរមា: A_max = 15 * 30 = 450 m^2 (1 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11748, 'ហាងលក់សម្លៀកបំពាក់មួយលក់អាវយឺតក្នុងតម្លៃបច្ចុប្បន្ន \(20\) ដុល្លារក្នុងមួយអាវ ដោយលក់បានជាមធ្យម \(100\) អាវក្នុងមួយសប្តាហ៍។ តាមការស្ទង់មតិ រាល់ពេលដែលហាងបញ្ចុះតម្លៃ \(1\) ដុល្លារ ចំនួនអាវលក់បាននឹងកើនឡើង \(10\) អាវបន្ថែម។ តាង \(x\) ជាចំនួនដងនៃការបញ្ចុះតម្លៃ 1 ដុល្លារ។
ក. សរសេរតម្លៃអាវមួយ និងចំនួនអាវលក់បានជាអនុគមន៍នៃ \(x\)។
ខ. បង្ហាញថាចំណូលសរុបប្រចាំសប្តាហ៍គឺ \(R(x) = -10x^2 + 100x + 2\,000\)។
គ. រកតម្លៃលក់អាវយឺតមួយដែលធ្វើឱ្យហាងទទួលបានចំណូលខ្ពស់បំផុត និងគណនាចំណូលខ្ពស់បំផុតនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តម្លៃអាវមួយ: 20 - x (ដុល្លារ), ចំនួនអាវលក់បាន: 100 + 10x (អាវ) (1 ពិន្ទុ)
ចំណូល R(x) = (20 - x)(100 + 10x) = 2000 + 200x - 100x - 10x^2 = -10x^2 + 100x + 2000 (1.5 ពិន្ទុ)
រក x ឱ្យចំណូលអតិបរមា: x = -100 / (2(-10)) = 5 ដង (បញ្ចុះ 5 ដុល្លារ) (1 ពិន្ទុ)
តម្លៃលក់សមស្រប: 20 - 5 = 15 ដុល្លារ/អាវ (0.75 ពិន្ទុ)
ចំណូលអតិបរមា: R(5) = -10(25) + 100(5) + 2000 = -250 + 500 + 2000 = 2250 ដុល្លារ (0.75 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11749, 'ក្លោងទ្វារចូលសួនកម្សាន្តមួយមានរាងជាប៉ារ៉ាបូលបើកចុះក្រោម។ ទទឹងបាតក្លោងទ្វារលើផ្ទៃដីគឺ \(8\text{ m}\) ហើយចំណុចកំពូលខ្ពស់បំផុតមានកម្ពស់ \(6\text{ m}\) ពីដី។
ក. ដោយជ្រើសរើសតម្រុយអ័ក្សដែលមានគល់ \(O\) នៅចំកណ្តាលបាតក្លោងទ្វារលើដី សរសេរសមីការប៉ារ៉ាបូល \(y = ax^2 + 6\)។
ខ. រកតម្លៃមេគុណ \(a\)។
គ. គណនាកម្ពស់ក្លោងទ្វារនៅត្រង់ចំណុចដែលមានចម្ងាយ \(2\text{ m}\) ពីចំណុចកណ្តាល \(O\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កូអរដោនេចំណុចបាត: ដោយទទឹង 8 m ចំណុចកាត់ដីគឺ (-4, 0) និង (4, 0) (1.5 ពិន្ទុ)
ជំនួស (4, 0) ក្នុងសមីការ: 0 = a(4)^2 + 6 នាំឱ្យ 16a = -6 នាំឱ្យ a = -6/16 = -3/8 = -0.375 (1.5 ពិន្ទុ)
សរសេរសមីការពេញលេញ: y = -0.375x^2 + 6 (0.5 ពិន្ទុ)
គណនាកម្ពស់នៅ x = 2 m: y = -0.375(2)^2 + 6 = -0.375(4) + 6 = -1.5 + 6 = 4.5 m (1.5 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11750, 'សហគ្រាសផលិតសម្ភារអេឡិចត្រូនិកមួយមានថ្លៃដើមសរុបប្រចាំខែ \(C(x) = 2x^2 + 20x + 100\) (គិតជាពាន់ដុល្លារ) និងចំណូលសរុប \(R(x) = 140x\) (គិតជាពាន់ដុល្លារ) ដែល \(x\) ជាចំនួនផលិតផល (គិតជារយគ្រឿង)។
ក. សរសេរកន្សោមអនុគមន៍ប្រាក់ចំណេញសុទ្ធ \(P(x) = R(x) - C(x)\)។
ខ. រកចំនួនផលិតផល \(x\) ដែលត្រូវផលិតដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា។
គ. គណនាប្រាក់ចំណេញអតិបរមានោះ (គិតជាដុល្លារ)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរ P(x) = 140x - (2x^2 + 20x + 100) = -2x^2 + 120x - 100 (ពាន់ដុល្លារ) (1.5 ពិន្ទុ)
រក x ត្រង់កំពូល: x = -120 / (2(-2)) = 30 (រយគ្រឿង) = 3000 គ្រឿង (1.5 ពិន្ទុ)
គណនាប្រាក់ចំណេញអតិបរមា: P(30) = -2(900) + 120(30) - 100 = -1800 + 3600 - 100 = 1700 ពាន់ដុល្លារ (1.5 ពិន្ទុ)
ប្តូរទៅជាដុល្លារ: 1700 * 1000 = 1,700,000 ដុល្លារ (0.5 ពិន្ទុ)', 'អនុគមន៍ដឺក្រេទី 2', 'pisa', 0, '10', 'អនុគមន៍ដឺក្រេទី 2', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11801, 'តើអនុគមន៍សនិទានជាអនុគមន៍មានទម្រង់បែបណា?', NULL, '["ផលធៀបនៃពហុធាពីរ f(x) = P(x)/Q(x) ដែល Q(x) មិនស្មើ 0", "អនុគមន៍ត្រីកោណមាត្រ", "អនុគមន៍លោការីត", "អនុគមន៍ដែលមានជាប់រ៉ាឌីកាល់"]', 0, NULL, 1, 'mcq', 'អនុគមន៍សនិទានគឺជាប្រភាគដែលភាគយកនិងភាគបែងសុទ្ធតែជាពហុធា។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11802, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{2x + 1}{x - 5}\)៖', NULL, '["\\(D = \\mathbb{R} \\setminus \\{-5\\}\\)", "\\(D = \\mathbb{R} \\setminus \\{5\\}\\)", "\\(D = \\mathbb{R}\\)", "\\(D = (5, +\\infty)\\)"]', 1, NULL, 1, 'mcq', 'អនុគមន៍មានន័យកាលណា x - 5 \neq 0 \Leftrightarrow x \neq 5 នាំឱ្យ D = \mathbb{R} \setminus \{5\}។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11803, 'រកសមីការអាស៊ីមតូតឈរនៃក្រាប \(y = \dfrac{3x - 1}{x - 4}\)៖', NULL, '["\\(x = -4\\)", "\\(y = 4\\)", "\\(y = 3\\)", "\\(x = 4\\)"]', 3, NULL, 1, 'mcq', 'អាស៊ីមតូតឈរកើតឡើងត្រង់ភាគបែងស្មើ 0៖ x - 4 = 0 <=> x = 4។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11804, 'រកចំណុចកាត់អ័ក្ស Oy នៃក្រាប \(y = \dfrac{2x - 6}{x + 3}\)៖', NULL, '["\\((-2, 0)\\)", "\\((0, -2)\\)", "\\((3, 0)\\)", "\\((0, 2)\\)"]', 1, NULL, 1, 'mcq', 'ជំនួស x = 0 នាំឱ្យ y = -6/3 = -2 ដូច្នេះចំណុចកាត់គឺ (0, -2)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11805, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{4}{3x + 6}\)៖', NULL, '["\\(D = \\mathbb{R} \\setminus \\{2\\}\\)", "\\(D = \\mathbb{R} \\setminus \\{-6\\}\\)", "\\(D = \\mathbb{R} \\setminus \\{-2\\}\\)", "\\(D = \\mathbb{R}\\)"]', 2, NULL, 1, 'mcq', '3x + 6 \neq 0 \Leftrightarrow 3x \neq -6 \Leftrightarrow x \neq -2 នាំឱ្យ D = \mathbb{R} \setminus \{-2\}។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11806, 'រកសមីការអាស៊ីមតូតដេកនៃក្រាប \(y = \dfrac{4x + 5}{2x - 1}\)៖', NULL, '["\\(y = -5\\)", "\\(y = 2\\)", "\\(y = 4\\)", "\\(x = \\dfrac{1}{2}\\)"]', 1, NULL, 1, 'mcq', 'អាស៊ីមតូតដេកនៃ y = (ax + b)/(cx + d) គឺ y = a/c = 4/2 = 2។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11807, 'រកចំណុចកាត់អ័ក្ស Ox នៃក្រាប \(y = \dfrac{3x - 9}{x + 1}\)៖', NULL, '["\\((-1, 0)\\)", "\\((3, 0)\\)", "\\((0, -9)\\)", "\\((9, 0)\\)"]', 1, NULL, 1, 'mcq', 'y = 0 \Leftrightarrow 3x - 9 = 0 \Leftrightarrow x = 3 ដូច្នេះចំណុចកាត់គឺ (3, 0)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11808, 'រកដែនកំណត់នៃអនុគមន៍អសនិទាន \(y = \sqrt{x - 3}\)៖', NULL, '["\\((3, +\\infty)\\)", "\\(\\mathbb{R}\\)", "\\((-\\infty, 3]\\)", "\\([3, +\\infty)\\)"]', 3, NULL, 1, 'mcq', 'កន្សោមក្រោមរ៉ាឌីកាល់មិនអវិជ្ជមាន៖ x - 3 \ge 0 \Leftrightarrow x \ge 3 នាំឱ្យ D = [3, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11809, 'រកសមីការអាស៊ីមតូតដេកនៃក្រាប \(y = \dfrac{3}{x + 2}\)៖', NULL, '["\\(y = 3\\)", "\\(y = 2\\)", "\\(x = -2\\)", "\\(y = 0\\)"]', 3, NULL, 1, 'mcq', 'ដឺក្រេភាគយក (0) តូចជាងដឺក្រេភាគបែង (1) នាំឱ្យអាស៊ីមតូតដេកគឺបន្ទាត់ y = 0 (អ័ក្ស Ox)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11810, 'រកដែនកំណត់នៃអនុគមន៍ \(y = \sqrt{2x + 8}\)៖', NULL, '["\\([-4, +\\infty)\\)", "\\([4, +\\infty)\\)", "\\((-4, +\\infty)\\)", "\\((-\\infty, -4]\\)"]', 0, NULL, 1, 'mcq', '2x + 8 \ge 0 \Leftrightarrow 2x \ge -8 \Leftrightarrow x \ge -4 នាំឱ្យ D = [-4, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
