INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11811, 'រកកូអរដោនេផ្ចិតឆ្លុះ I នៃក្រាប \(y = \dfrac{3x - 2}{x - 1}\)៖', 'g10-372b3955a4.svg', '["\\(I(1, 3)\\)", "\\(I(1, -2)\\)", "\\(I(3, 1)\\)", "\\(I(-1, 3)\\)"]', 0, NULL, 2, 'mcq', 'ផ្ចិតឆ្លុះ I ជាប្រសព្វនៃអាស៊ីមតូតឈរ x = 1 និងអាស៊ីមតូតដេក y = 3/1 = 3 នាំឱ្យ I(1, 3)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11812, 'បំប្លែង \(y = \dfrac{2x + 5}{x + 1}\) ជាទម្រង់ \(y = q + \dfrac{k}{x - p}\)៖', NULL, '["\\(y = 2 + \\dfrac{3}{x + 1}\\)", "\\(y = 2 - \\dfrac{3}{x + 1}\\)", "\\(y = 1 + \\dfrac{4}{x + 1}\\)", "\\(y = 2 + \\dfrac{5}{x + 1}\\)"]', 0, NULL, 2, 'mcq', '2x + 5 = 2(x + 1) + 3 នាំឱ្យ y = \dfrac{2(x + 1) + 3}{x + 1} = 2 + \dfrac{3}{x + 1}។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11813, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{16 - x^2}\)៖', NULL, '["\\([0, 4]\\)", "\\((-\\infty, -4] \\cup [4, +\\infty)\\)", "\\((-4, 4)\\)", "\\([-4, 4]\\)"]', 3, NULL, 2, 'mcq', '16 - x^2 \ge 0 \Leftrightarrow x^2 \le 16 \Leftrightarrow -4 \le x \le 4 នាំឱ្យ D = [-4, 4]។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11814, 'រកសំណុំរូបភាពនៃអនុគមន៍ \(y = \sqrt{x - 4} + 3\)៖', NULL, '["\\((3, +\\infty)\\)", "\\(\\mathbb{R}\\)", "\\([3, +\\infty)\\)", "\\([4, +\\infty)\\)"]', 2, NULL, 2, 'mcq', 'ដោយ \sqrt{x - 4} \ge 0 នាំឱ្យ y \ge 3 ដូច្នេះសំណុំរូបភាពគឺ [3, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
