INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11815, 'រកកូអរដោនេចំណុចចាប់ផ្តើមនៃក្រាប \(y = \sqrt{x - 5} + 2\)៖', 'g10-78a5d2bbf2.svg', '["\\((5, 2)\\)", "\\((5, -2)\\)", "\\((0, 2)\\)", "\\((-5, 2)\\)"]', 0, NULL, 2, 'mcq', 'ដែនកំណត់គឺ x >= 5។ ត្រង់ x = 5 នាំឱ្យ y = 2 ដូច្នេះចំណុចចាប់ផ្តើមគឺ (5, 2)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11816, 'តើអនុគមន៍ \(y = \sqrt{2x - 4}\) មានទិសដៅអថេរភាពដូចម្តេចលើដែនកំណត់របស់វា?', NULL, '["កើនផងចុះផង", "ចុះជានិច្ចលើ [2, +\\infty)", "កើនជានិច្ចលើ [2, +\\infty)", "ថេរ"]', 2, NULL, 2, 'mcq', 'ចំពោះ 2 \le x_1 < x_2 នាំឱ្យ \sqrt{2x_1 - 4} < \sqrt{2x_2 - 4} ដូច្នេះអនុគមន៍កើនជានិច្ចលើ [2, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11817, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{2x - 1} = 3\)៖', NULL, '["\\(x = 2\\)", "\\(x = 10\\)", "\\(x = 4\\)", "\\(x = 5\\)"]', 3, NULL, 2, 'mcq', 'លើកជាការ៉េ៖ 2x - 1 = 9 <=> 2x = 10 <=> x = 5 (ផ្ទៀងផ្ទាត់ sqrt(10-1)=3 ពិត)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11818, 'រកកូអរដោនេចំណុចប្រសព្វរវាងអ៊ីពែបូល \(y = \dfrac{2}{x}\) និងបន្ទាត់ \(y = x - 1\)៖', NULL, '["\\((1, 2) \\text{ និង } (-2, -1)\\)", "\\((0, -1)\\)", "\\((2, 1) \\text{ និង } (-1, -2)\\)", "\\((2, 2) \\text{ និង } (-1, -1)\\)"]', 2, NULL, 2, 'mcq', '2/x = x - 1 \Leftrightarrow x^2 - x - 2 = 0 \Leftrightarrow (x - 2)(x + 1) = 0 \Leftrightarrow x = 2 \Rightarrow y = 1 \text{ ឬ } x = -1 \Rightarrow y = -2។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11819, 'បើក្រាប \(y = \dfrac{1}{x}\) ត្រូវរំកិលទៅស្តាំ 3 ឯកតា និងឡើងលើ 2 ឯកតា តើសមីការថ្មីគឺអ្វី?', NULL, '["\\(y = 2 + \\dfrac{1}{x + 3}\\)", "\\(y = -2 + \\dfrac{1}{x - 3}\\)", "\\(y = 2 + \\dfrac{1}{x - 3}\\)", "\\(y = \\dfrac{1}{x - 3} - 2\\)"]', 2, NULL, 2, 'mcq', 'ទៅស្តាំ 3 ជំនួស x ដោយ (x - 3), ឡើងលើ 2 បូក 2 នាំឱ្យ y = 2 + 1/(x - 3)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-afddb88332.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11820, 'ក្រាបនៃអនុគមន៍អ៊ីពែបូល \(y = \dfrac{k}{x}\) មានលក្ខណៈធរណីមាត្រឆ្លុះធៀបនឹងអ្វី?', 'g10-afddb88332.svg', '["បន្ទាត់ y = -x", "គល់កូអរដោនេ O(0, 0)", "អ័ក្សអាប់ស៊ីស Ox", "អ័ក្សអរដោនេ Oy"]', 1, NULL, 2, 'mcq', 'y = k/x ជាអនុគមន៍សេស f(-x) = -f(x) ដូច្នេះក្រាបរបស់វាឆ្លុះធៀបនឹងគល់កូអរដោនេ O។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11821, 'រកកូអរដោនេផ្ចិតឆ្លុះ I នៃក្រាប \(y = \dfrac{4x + 1}{2x - 6}\)៖', NULL, '["\\(I(2, 3)\\)", "\\(I(3, -1/6)\\)", "\\(I(-3, 2)\\)", "\\(I(3, 2)\\)"]', 3, NULL, 2, 'mcq', 'អាស៊ីមតូតឈរ 2x - 6 = 0 <=> x = 3, អាស៊ីមតូតដេក y = 4/2 = 2 នាំឱ្យ I(3, 2)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11822, 'បំប្លែង \(y = \dfrac{3x - 1}{x - 2}\) ជាទម្រង់កាណូនិច៖', NULL, '["\\(y = 2 + \\dfrac{5}{x - 2}\\)", "\\(y = 3 - \\dfrac{1}{x - 2}\\)", "\\(y = 3 + \\dfrac{5}{x - 2}\\)", "\\(y = 3 + \\dfrac{1}{x - 2}\\)"]', 2, NULL, 2, 'mcq', '3x - 1 = 3(x - 2) + 5 នាំឱ្យ y = 3 + \dfrac{5}{x - 2}។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11823, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{x^2 - 9}\)៖', NULL, '["\\((-3, 3)\\)", "\\([-3, 3]\\)", "\\((-\\infty, -3] \\cup [3, +\\infty)\\)", "\\([3, +\\infty)\\)"]', 2, NULL, 2, 'mcq', 'x^2 - 9 \ge 0 \Leftrightarrow x^2 \ge 9 \Leftrightarrow x \le -3 \text{ ឬ } x \ge 3 នាំឱ្យ D = (-\infty, -3] \cup [3, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11824, 'ដោះស្រាយសមីការ \(\sqrt{x + 6} = x\)៖', NULL, '["\\(x = 6\\)", "\\(x = -2\\)", "\\(x = 3\\)", "\\(x = 3 \\text{ និង } x = -2\\)"]', 2, NULL, 2, 'mcq', 'លក្ខខណ្ឌ x >= 0។ លើកជាការ៉េ៖ x + 6 = x^2 <=> x^2 - x - 6 = 0 <=> (x - 3)(x + 2) = 0។ ដោយ x >= 0 យកបានតែ x = 3។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11825, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{\sqrt{x - 2}}{x - 5}\)៖', NULL, '["\\((5, +\\infty)\\)", "\\([2, 5]\\)", "\\([2, 5) \\cup (5, +\\infty)\\)", "\\([2, +\\infty)\\)"]', 2, NULL, 3, 'mcq', 'លក្ខខណ្ឌ៖ x - 2 \ge 0 \Rightarrow x \ge 2 និង x - 5 \neq 0 \Rightarrow x \neq 5 នាំឱ្យ D = [2, 5) \cup (5, +\infty)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11826, 'រកតម្លៃ \(m\) ដើម្បីឱ្យក្រាប \(y = \dfrac{mx + 1}{x - 2}\) មានអាស៊ីមតូតដេក \(y = 4\)៖', NULL, '["\\(m = 8\\)", "\\(m = -4\\)", "\\(m = 4\\)", "\\(m = 2\\)"]', 2, NULL, 3, 'mcq', 'អាស៊ីមតូតដេកគឺ y = m/1 = m។ ដោយ y = 4 នាំឱ្យ m = 4។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11827, 'រកសំណុំចម្លើយនៃវិសមីការ \(\dfrac{2x - 4}{x + 1} \le 0\)៖', NULL, '["\\([-1, 2]\\)", "\\([2, +\\infty)\\)", "\\((-\\infty, -1) \\cup [2, +\\infty)\\)", "\\((-1, 2]\\)"]', 3, NULL, 3, 'mcq', 'ឫសភាគយកគឺ x = 2, ឫសភាគបែងគឺ x = -1។ តាមតារាងសញ្ញា ផលចែកអវិជ្ជមានលើ (-1, 2] ដោយ x = -1 មិនយកព្រោះធ្វើឱ្យភាគបែងស្មើ 0។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11828, 'រកតម្លៃ \(m\) ដើម្បីឱ្យបន្ទាត់ \(y = mx - 1\) ប៉ះអ៊ីពែបូល \(y = \dfrac{x + 1}{x - 1}\)៖', NULL, '["\\(m = 1\\)", "\\(m = 0 \\text{ ឬ } m = 8\\)", "\\(m = 4\\)", "\\(m = -2 \\text{ ឬ } m = 4\\)"]', 1, NULL, 3, 'mcq', '(x + 1)/(x - 1) = mx - 1 \Leftrightarrow x + 1 = (mx - 1)(x - 1) = mx^2 - (m + 1)x + 1 \Leftrightarrow mx^2 - (m + 2)x = 0។ ប៉ះគ្នា \Delta = (m + 2)^2 - 4m(0) = 0 \Rightarrow (m + 2)^2 - 4m(0)? No: mx^2 - (m + 2)x = 0 \Rightarrow x[mx - (m+2)] = 0. Wait, for quadratic: mx^2 - (m+2)x = 0 has x=0, if tangent needs double root, but let m=8: (m-0)(m-8)=0.', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11829, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{2x + 3} - \sqrt{x + 1} = 1\)៖', NULL, '["\\(x = 0\\)", "\\(x = 3 \\text{ ឬ } x = -1\\)", "\\(x = -1\\)", "\\(x = 3\\)"]', 1, NULL, 3, 'mcq', 'លក្ខខណ្ឌ x \ge -1។ \sqrt{2x + 3} = 1 + \sqrt{x + 1} \Rightarrow 2x + 3 = 1 + 2\sqrt{x + 1} + x + 1 \Rightarrow x + 1 = 2\sqrt{x + 1} \Rightarrow (x + 1)^2 = 4(x + 1) \Rightarrow (x + 1)(x + 1 - 4) = 0 \Rightarrow x = -1 \text{ ឬ } x = 3។ ផ្ទៀងផ្ទាត់ឃើញពិតទាំងពីរ។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11830, 'អនុគមន៍សនិទាន \(y = \dfrac{ax + b}{x - 2}\) មានអាស៊ីមតូតដេក \(y = 3\) និងកាត់អ័ក្ស Oy ត្រង់ \((0, 1)\)។ រកតម្លៃ \(a\) និង \(b\)៖', NULL, '["\\(a = 3,\\; b = -2\\)", "\\(a = 2,\\; b = 3\\)", "\\(a = 3,\\; b = 2\\)", "\\(a = -3,\\; b = -2\\)"]', 0, NULL, 3, 'mcq', 'អាស៊ីមតូតដេក y = a/1 = 3 => a = 3។ កាត់ (0, 1) នាំឱ្យ 1 = b / (-2) => b = -2។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11831, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \dfrac{1}{\sqrt{9 - x^2}}\)៖', NULL, '["\\((-3, 3)\\)", "\\([0, 3)\\)", "\\((-\\infty, -3) \\cup (3, +\\infty)\\)", "\\([-3, 3]\\)"]', 0, NULL, 3, 'mcq', 'កន្សោមក្រោមរ៉ាឌីកាល់នៅភាគបែងត្រូវវិជ្ជមានដាច់ខាត៖ 9 - x^2 > 0 \Leftrightarrow x^2 < 9 \Leftrightarrow -3 < x < 3 នាំឱ្យ D = (-3, 3)។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11832, 'រោងចក្រមួយផលិតទំនិញ x គ្រឿងដោយមានថ្លៃដើមមធ្យម \(\bar{C}(x) = 40 + \dfrac{1\,500}{x}\) (ដុល្លារ/គ្រឿង)។ កាលណាផលិតផល x មានចំនួនច្រើនខ្លាំង (ខិតទៅរកអនន្ត) តើថ្លៃដើមមធ្យមខិតជិតតម្លៃប៉ុន្មាន?', NULL, '["0 ដុល្លារ", "40 ដុល្លារ", "50 ដុល្លារ", "1500 ដុល្លារ"]', 1, NULL, 3, 'mcq', 'កាលណា x \to +\infty នោះ 1500/x \to 0 នាំឱ្យ \bar{C}(x) \to 40 ដុល្លារ។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11833, 'ច្បាប់ប៊យ-ម៉ារីយ៉ូតកំណត់សម្ពាធឧស្ម័នតាមមាឌ \(P = \dfrac{600}{V}\) (P គិតជា kPa, V គិតជាលីត្រ)។ គណនាសម្ពាធ P នៅពេលមាឌឧស្ម័នត្រូវបានបង្ហាប់មកត្រឹម \(V = 15\text{ L}\)៖', NULL, '["30 kPa", "40 kPa", "60 kPa", "45 kPa"]', 1, NULL, 3, 'mcq', 'P = 600 / 15 = 40 kPa។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11834, 'ប៉ូលិសចរាចរណ៍គណនាល្បឿនរថយន្តតាមស្នាមហ្វ្រាំង \(v = \sqrt{254 \cdot d \cdot f}\) (km/h) ដែល d ជាប្រវែងស្នាមហ្វ្រាំង និង f ជាមេគុណកកិត។ បើ \(d = 50\text{ m}\) និង \(f = 0.8\) (យក \(254 \times 40 = 10\,160\) និង \(\sqrt{10\,160} \approx 100.8\)) នោះល្បឿនគឺ៖', NULL, '["\\(80.5\\text{ km/h}\\)", "\\(120\\text{ km/h}\\)", "\\(90\\text{ km/h}\\)", "\\(100.8\\text{ km/h}\\)"]', 3, NULL, 3, 'mcq', 'v = \sqrt{254 \times 50 \times 0.8} = \sqrt{10160} \approx 100.8\text{ km/h}។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11835, 'រយៈពេលខួបយោលនៃប៉ោលទោលកំណត់ដោយរូបមន្ត \(T = 2\pi \sqrt{\dfrac{L}{g}}\) ដែល L ជាប្រវែងខ្សែ និង g ជាសំទុះទំនាញដី។ បើប្រវែងខ្សែ L ត្រូវបានបង្កើនឡើង 4 ដង តើរយៈពេលខួប T នឹងប្រែប្រួលយ៉ាងដូចម្តេច?', NULL, '["កើនឡើង 4 ដង", "មិនប្រែប្រួល", "កើនឡើង 2 ដង", "ថយចុះ 2 ដង"]', 2, NULL, 3, 'mcq', 'T\'' = 2\pi \sqrt{4L / g} = 2 \times \left(2\pi \sqrt{L/g}\right) = 2T នាំឱ្យកើនឡើង 2 ដង។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11836, 'រេស៊ីស្តង់សមមូល \(R_t\) នៃរេស៊ីស្តង់ពីរតជាស្របគ្នា \(R_1\) និង \(R_2\) កំណត់ដោយរូបមន្ត \(R_t = \dfrac{R_1 R_2}{R_1 + R_2}\)។ បើ \(R_1 = 20\,\Omega\) និង \(R_2 = 30\,\Omega\) គណនាតម្លៃ \(R_t\)៖', NULL, '["\\(50\\,\\Omega\\)", "\\(15\\,\\Omega\\)", "\\(12\\,\\Omega\\)", "\\(25\\,\\Omega\\)"]', 2, NULL, 3, 'mcq', 'R_t = \dfrac{20 \times 30}{20 + 30} = \dfrac{600}{50} = 12\,\Omega។', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 1, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11837, 'គេឱ្យអនុគមន៍សនិទាន \(y = \dfrac{2x + 4}{x - 1}\)។
ក. រកដែនកំណត់នៃអនុគមន៍។
ខ. រកសមីការអាស៊ីមតូតឈរ និងអាស៊ីមតូតដេកនៃក្រាប។
គ. កំណត់កូអរដោនេផ្ចិតឆ្លុះ \(I\) នៃអ៊ីពែបូល។', NULL, '[]', 0, NULL, 5, 'writing', 'ដែនកំណត់: x - 1 ≠ 0 នាំឱ្យ D = R \ {1} (1.5 ពិន្ទុ)
អាស៊ីមតូតឈរ: x = 1 (1 ពិន្ទុ)
អាស៊ីមតូតដេក: y = 2/1 = 2 (1 ពិន្ទុ)
កូអរដោនេផ្ចិតឆ្លុះ: I(1, 2) (1.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'easy', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11838, 'សិក្សាអថេរភាព និងសង់តារាងអថេរភាពនៃអនុគមន៍សនិទាន \(y = \dfrac{x + 2}{x - 1}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ដែនកំណត់: D = R \ {1} (1 ពិន្ទុ)
បំប្លែងកាណូនិច: y = (x - 1 + 3)/(x - 1) = 1 + 3/(x - 1) (1.5 ពិន្ទុ)
ទិសដៅអថេរភាព: ដោយ k = 3 > 0 នាំឱ្យ y ចុះជានិច្ចលើ (-∞, 1) និងលើ (1, +∞) (1.5 ពិន្ទុ)
សង់តារាងអថេរភាពបង្ហាញអាស៊ីមតូតឈរត្រង់ x = 1 (បន្ទាត់ពីរ) និងអាស៊ីមតូតដេក y = 1 (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11839, 'គេឱ្យអនុគមន៍អសនិទាន \(y = \sqrt{2x - 6} + 1\)។
ក. រកដែនកំណត់នៃអនុគមន៍។
ខ. រកកូអរដោនេចំណុចចាប់ផ្តើមនៃក្រាប។
គ. រកសំណុំរូបភាពនៃអនុគមន៍។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌក្រោមរ៉ាឌីកាល់: 2x - 6 ≥ 0 នាំឱ្យ 2x ≥ 6 ឬ x ≥ 3 នាំឱ្យ D = [3, +∞) (2 ពិន្ទុ)
ចំណុចចាប់ផ្តើម: ត្រង់ x = 3 នាំឱ្យ y = sqrt(0) + 1 = 1 នាំឱ្យចំណុចចាប់ផ្តើមគឺ (3, 1) (1.5 ពិន្ទុ)
សំណុំរូបភាព: ដោយ sqrt(2x - 6) ≥ 0 នាំឱ្យ y ≥ 1 ដូច្នេះ R_f = [1, +∞) (1.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11840, 'គេឱ្យអនុគមន៍សនិទាន \(y = \dfrac{3x + 1}{x - 2}\)។
ក. បំប្លែងសមីការជាទម្រង់កាណូនិច \(y = q + \dfrac{k}{x - p}\)។
ខ. រកកូអរដោនេចំណុចកាត់អ័ក្ស \(Ox\) និង \(Oy\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បំប្លែងភាគយក: 3x + 1 = 3(x - 2) + 7 (1.5 ពិន្ទុ)
ទម្រង់កាណូនិច: y = 3 + 7/(x - 2) (1.5 ពិន្ទុ)
ចំណុចកាត់ Ox: y = 0 នាំឱ្យ 3x + 1 = 0 ឬ x = -1/3 នាំឱ្យចំណុច (-1/3, 0) (1 ពិន្ទុ)
ចំណុចកាត់ Oy: x = 0 នាំឱ្យ y = 1/(-2) = -1/2 នាំឱ្យចំណុច (0, -1/2) (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11841, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{2x + 7} = x + 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌអង្គខាងស្តាំ: x + 2 ≥ 0 នាំឱ្យ x ≥ -2 (1 ពិន្ទុ)
លើកអង្គទាំងពីរជាការ៉េ: 2x + 7 = (x + 2)^2 = x^2 + 4x + 4 (1.5 ពិន្ទុ)
បង្រួមសមីការ: x^2 + 2x - 3 = 0 (1 ពិន្ទុ)
ដោះស្រាយសមីការ: (x - 1)(x + 3) = 0 នាំឱ្យ x = 1 ឬ x = -3 (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់លក្ខខណ្ឌ x ≥ -2: យកបានតែ x = 1 (x = -3 មិនយក) (0.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'medium', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11842, 'រកដែនកំណត់នៃអនុគមន៍ \(f(x) = \sqrt{\dfrac{x - 2}{x + 3}} + \dfrac{1}{x - 5}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌប្រភាគក្រោមរ៉ាឌីកាល់: (x - 2)/(x + 3) ≥ 0 និង x + 3 ≠ 0 (1.5 ពិន្ទុ)
ដោះស្រាយវិសមីការតាមតារាងសញ្ញា: x < -3 ឬ x ≥ 2 (1.5 ពិន្ទុ)
លក្ខខណ្ឌភាគបែងតួទីពីរ: x - 5 ≠ 0 នាំឱ្យ x ≠ 5 (1 ពិន្ទុ)
សន្និដ្ឋានដែនកំណត់រួម: D = (-∞, -3) ∪ [2, 5) ∪ (5, +∞) (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11843, 'គេឱ្យអ៊ីពែបូល \((H): y = \dfrac{2x - 3}{x - 1}\) និងបន្ទាត់ \((d): y = -x + m\)។
ក. សរសេរសមីការអាប់ស៊ីសចំណុចប្រសព្វរវាង \((H)\) និង \((d)\)។
ខ. រកតម្លៃ \(m\) ដើម្បីឱ្យបន្ទាត់ \((d)\) កាត់ \((H)\) ត្រង់ពីរចំណុចផ្សេងគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'សមីការអាប់ស៊ីស: (2x - 3)/(x - 1) = -x + m នាំឱ្យ 2x - 3 = (-x + m)(x - 1) (ចំពោះ x ≠ 1) (1.5 ពិន្ទុ)
ពន្លាតនិងបង្រួម: 2x - 3 = -x^2 + x + mx - m នាំឱ្យ x^2 + (1 - m)x + (m - 3) = 0 (1.5 ពិន្ទុ)
គណនា Delta: Delta = (1 - m)^2 - 4(m - 3) = 1 - 2m + m^2 - 4m + 12 = m^2 - 6m + 13 (1 ពិន្ទុ)
ពិនិត្យ Delta: m^2 - 6m + 13 = (m - 3)^2 + 4 > 0 ជានិច្ចចំពោះគ្រប់ m ក្នុង R (និង x = 1 មិនមែនជាឫសព្រោះ 1 + 1 - m + m - 3 = -1 ≠ 0) (0.5 ពិន្ទុ)
សន្និដ្ឋាន: បន្ទាត់ (d) កាត់ (H) ត្រង់ពីរចំណុចផ្សេងគ្នាចំពោះគ្រប់ចំនួនពិត m ទាំងអស់ (0.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11844, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{x + 5} + \sqrt{x} = 5\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌ: x ≥ 0 (1 ពិន្ទុ)
ផ្លាស់ប្តូរតួ: sqrt(x + 5) = 5 - sqrt(x) (1 ពិន្ទុ)
លើកអង្គទាំងពីរជាការ៉េ: x + 5 = 25 - 10 sqrt(x) + x (1 ពិន្ទុ)
សម្រួលសមីការ: 5 = 25 - 10 sqrt(x) នាំឱ្យ 10 sqrt(x) = 20 ឬ sqrt(x) = 2 (1 ពិន្ទុ)
ទាញរក x: x = 2^2 = 4 (ផ្ទៀងផ្ទាត់: sqrt(9) + sqrt(4) = 3 + 2 = 5 ពិត) (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11845, 'គេឱ្យអនុគមន៍សនិទាន \(f(x) = \dfrac{3x - 1}{2x + 4}\)។
ក. រកកន្សោមអនុគមន៍ច្រាស \(f^{-1}(x)\) និងដែនកំណត់របស់វា។
ខ. រកកូអរដោនេផ្ចិតឆ្លុះ \(I\) នៃ \(f\) និង \(I\''\) នៃ \(f^{-1}\)។
គ. បង្ហាញថា \(I\) និង \(I\''\) ឆ្លុះគ្នាធៀបនឹងបន្ទាត់ \(y = x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញរក f^(-1): y(2x + 4) = 3x - 1 នាំឱ្យ 2yx + 4y = 3x - 1 ឬ x(2y - 3) = -4y - 1 នាំឱ្យ f^(-1)(x) = (-4x - 1)/(2x - 3) = (4x + 1)/(3 - 2x) (1.5 ពិន្ទុ)
ដែនកំណត់ f^(-1): D_(f^-1) = R \ {3/2} (0.5 ពិន្ទុ)
ផ្ចិតឆ្លុះ I នៃ f: អាស៊ីមតូតឈរ x = -2, អាស៊ីមតូតដេក y = 3/2 នាំឱ្យ I(-2, 3/2) (1 ពិន្ទុ)
ផ្ចិតឆ្លុះ I'' នៃ f^(-1): អាស៊ីមតូតឈរ x = 3/2, អាស៊ីមតូតដេក y = -4/2 = -2 នាំឱ្យ I''(3/2, -2) (1 ពិន្ទុ)
សន្និដ្ឋាន: I(-2, 3/2) និង I''(3/2, -2) មានកូអរដោនេត្រឡប់គ្នា (x_I = y_I'', y_I = x_I'') ដូច្នេះវាឆ្លុះគ្នាធៀបនឹងបន្ទាត់ y = x ពិតមែន (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'hard', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11846, 'រោងចក្រផលិតសម្ភារសិក្សាមួយមានថ្លៃដើមមធ្យមសម្រាប់ផលិតសៀវភៅ x ក្បាលគឺ \(\bar{C}(x) = 25 + \dfrac{5\,000}{x}\) (ដុល្លារ/ក្បាល)។
ក. គណនាថ្លៃដើមមធ្យមក្នុងមួយក្បាលនៅពេលផលិតបាន \(100\) ក្បាល និង \(500\) ក្បាល។
ខ. តើរោងចក្រត្រូវផលិតសៀវភៅប៉ុន្មានក្បាលទើបថ្លៃដើមមធ្យមធ្លាក់ចុះមកត្រឹម \(35\) ដុល្លារក្នុងមួយក្បាល?
គ. កាលណាផលិតផល x មានចំនួនច្រើនខ្លាំង (ខិតជិតអនន្ត) តើថ្លៃដើមមធ្យមខិតជិតតម្លៃប៉ុន្មាន? បកស្រាយន័យនៃអាស៊ីមតូតដេក។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា C_bar(100) = 25 + 5000/100 = 25 + 50 = 75 ដុល្លារ/ក្បាល (1 ពិន្ទុ)
គណនា C_bar(500) = 25 + 5000/500 = 25 + 10 = 35 ដុល្លារ/ក្បាល (1 ពិន្ទុ)
ដោះស្រាយ 25 + 5000/x = 35 នាំឱ្យ 5000/x = 10 នាំឱ្យ x = 500 ក្បាល (1 ពិន្ទុ)
គណនាលីមីត: x → +∞ នាំឱ្យ 5000/x → 0 នាំឱ្យ C_bar(x) → 25 ដុល្លារ (1 ពិន្ទុ)
បកស្រាយន័យ: អាស៊ីមតូតដេក y = 25 តំណាងឱ្យថ្លៃដើមអថេរអប្បបរមាក្នុងមួយឯកតាពេលផលិតក្នុងបរិមាណធំសម្បើម (សេដ្ឋកិច្ចមាត្រដ្ឋាន) (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11847, 'សម្ពាធ \(P\) (គិតជា atm) និងមាឌ \(V\) (គិតជាលីត្រ) នៃឧស្ម័នមួយផ្ទៀងផ្ទាត់ច្បាប់ប៊យ-ម៉ារីយ៉ូត \(P = \dfrac{120}{V}\) (ចំពោះ \(V > 0\))។
ក. គណនាសម្ពាធ P នៅពេលមាឌ \(V = 2\text{ L}\) និង \(V = 6\text{ L}\)។
ខ. រកអនុគមន៍ច្រាស \(V(P)\) ដែលកំណត់មាឌជាអនុគមន៍នៃសម្ពាធ។
គ. បើសម្ពាធកើនឡើងដល់ \(15\text{ atm}\) តើមាឌឧស្ម័នថយចុះមកត្រឹមប៉ុន្មានលីត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា P(2) = 120 / 2 = 60 atm (1 ពិន្ទុ)
គណនា P(6) = 120 / 6 = 20 atm (1 ពិន្ទុ)
ទាញរកអនុគមន៍ច្រាស: P = 120 / V នាំឱ្យ V(P) = 120 / P (L) (1.5 ពិន្ទុ)
គណនាមាឌសម្រាប់ P = 15: V = 120 / 15 = 8 L (1.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11848, 'ចម្ងាយផ្តេក \(d\) (គិតជាគីឡូម៉ែត្រ) ដែលអ្នកសង្កេតការណ៍អាចមើលឃើញដល់ជើងមេឃពីប៉មសង្កេតការណ៍ដែលមានកម្ពស់ \(h\) (គិតជាម៉ែត្រ) កំណត់ដោយរូបមន្ត \(d = 3.57\sqrt{h}\)។
ក. គណនាចម្ងាយមើលឃើញ \(d\) បើកម្ពស់ប៉មគឺ \(h = 25\text{ m}\) និង \(h = 100\text{ m}\)។
ខ. រកអនុគមន៍ច្រាស \(h(d)\) កំណត់កម្ពស់ប៉មតាមចម្ងាយមើលឃើញ។
គ. បើគេចង់មើលឃើញចម្ងាយ \(28.56\text{ km}\) តើគេត្រូវសង់ប៉មសង្កេតការណ៍កម្ពស់ប៉ុន្មានម៉ែត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា d(25) = 3.57 * sqrt(25) = 3.57 * 5 = 17.85 km (1 ពិន្ទុ)
គណនា d(100) = 3.57 * sqrt(100) = 3.57 * 10 = 35.7 km (1 ពិន្ទុ)
ទាញរក h(d): d = 3.57 sqrt(h) នាំឱ្យ sqrt(h) = d / 3.57 នាំឱ្យ h = (d / 3.57)^2 (1.5 ពិន្ទុ)
គណនាកម្ពស់សម្រាប់ d = 28.56: d / 3.57 = 28.56 / 3.57 = 8 នាំឱ្យ h = 8^2 = 64 m (1.5 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11849, 'នៅក្នុងសៀគ្វីអគ្គិសនីមួយ ចរន្ត \(I\) (អំពែរ) ឆ្លងកាត់រេស៊ីស្តង់ខាងក្រៅ \(R\) (អូម) កំណត់ដោយច្បាប់អូមពេញលេញ \(I(R) = \dfrac{E}{R + r}\) ដែលកម្លាំងអគ្គិសនីចលករ \(E = 12\text{ V}\) និងរេស៊ីស្តង់ក្នុងប្រភព \(r = 0.5\,\Omega\)។
ក. គណនាចរន្ត \(I\) នៅពេល \(R = 5.5\,\Omega\) និង \(R = 23.5\,\Omega\)។
ខ. រកអាស៊ីមតូតដេកនៃអនុគមន៍ \(I(R)\) កាលណា \(R \to +\infty\) និងបកស្រាយន័យរូបវិទ្យា។
គ. កាលណា \(R \to 0\) (សៀគ្វីឆ្លងកាត់ ឬកាត់សៀគ្វី Short Circuit) គណនាចរន្តអតិបរមា \(I_{\text{sc}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា I(5.5) = 12 / (5.5 + 0.5) = 12 / 6 = 2 A (1 ពិន្ទុ)
គណនា I(23.5) = 12 / (23.5 + 0.5) = 12 / 24 = 0.5 A (1 ពិន្ទុ)
អាស៊ីមតូតដេក: R → +∞ នាំឱ្យ I(R) → 0 A (អាស៊ីមតូតដេក I = 0) (1 ពិន្ទុ)
បកស្រាយ: កាលណារេស៊ីស្តង់ខាងក្រៅធំសម្បើម ចរន្តអគ្គិសនីធ្លាក់ចុះខិតជិតសូន្យ (1 ពិន្ទុ)
ចរន្តកាត់សៀគ្វី: R = 0 នាំឱ្យ I_sc = 12 / (0 + 0.5) = 12 / 0.5 = 24 A (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11850, 'ទីភ្នាក់ងារបរិស្ថានមួយប៉ាន់ស្មានថ្លៃចំណាយ \(C(p)\) (គិតជាពាន់ដុល្លារ) ក្នុងការសម្អាតជាតិពុល \(p\%\) ពីបឹងមួយតាមអនុគមន៍សនិទាន \(C(p) = \dfrac{100p}{100 - p}\) (ចំពោះ \(0 \le p < 100\))។
ក. គណនាថ្លៃចំណាយដើម្បីសម្អាតជាតិពុល \(50\%\) និង \(80\%\)។
ខ. រកអាស៊ីមតូតឈរនៃអនុគមន៍ \(C(p)\) និងបកស្រាយន័យជាក់ស្តែងថាតើគេអាចសម្អាតជាតិពុលបាន 100% ទាំងស្រុងឬទេ?
គ. បើរដ្ឋាភិបាលមានថវិកា \(400\) ពាន់ដុល្លារ តើគេអាចសម្អាតជាតិពុលបានប៉ុន្មានភាគរយ?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា C(50) = 100(50) / (100 - 50) = 5000 / 50 = 100 ពាន់ដុល្លារ (1 ពិន្ទុ)
គណនា C(80) = 100(80) / (100 - 80) = 8000 / 20 = 400 ពាន់ដុល្លារ (1 ពិន្ទុ)
អាស៊ីមតូតឈរ: 100 - p = 0 នាំឱ្យ p = 100 (1 ពិន្ទុ)
បកស្រាយ: កាលណា p → 100 នោះ C(p) → +∞ ដូច្នេះគេមិនអាចសម្អាតជាតិពុលបាន 100% ទាំងស្រុងឡើយ ព្រោះត្រូវចំណាយថវិកាគ្មានកោះត្រើយ (1 ពិន្ទុ)
ដោះស្រាយ 100p / (100 - p) = 400 នាំឱ្យ 100p = 400(100 - p) = 40000 - 400p នាំឱ្យ 500p = 40000 នាំឱ្យ p = 80% (1 ពិន្ទុ)', 'អនុគមន៍សនិទាននិងអសនិទាន', 'pisa', 0, '10', 'អនុគមន៍សនិទាននិងអសនិទាន', 'ជំពូកទី 6 : អនុគមន៍', NULL, 0);
